  --shadow-lift:0 0 0 1px rgba(0,0,0,.05),0 2px 4px rgba(0,0,0,.04),0 16px 32px -10px rgba(0,0,0,.16);
  /* the accent has three roles: --accent fills (with --on-accent on top, 4.5:1), --accent-fg is text and icons in the accent
     (4.5:1 on the surface, and on the chips and tints it sits on) and --accent-mark is lines, rings and chart marks (3:1). A
     light accent like lime keeps its fills and gets a darker mark and ink-coloured text on a light page */ --sel:color-mix(in srgb,var(--accent) 6%,transparent);
  /* fields (text fields, textareas, search fields, dropdown triggers) have a dimmed grey edge, --field-line, that steps up
     a little, to --field-line-strong, while they have the focus. The keyboard's focus ring on every other control is 2px of
     a stronger grey (--line-strong, as --focus), as an outline offset 2px, or as a 2px box-shadow ring where an outline would be clipped. Never
     the accent and never black, and only from the keyboard (:focus-visible), so a click or a tap never shows one */
  --focus:var(--line-strong);
  --ink:#1b1b1b; --on-ink:#ffffff;
  /* the status tints sit with the core tag colours below (21 Nov): a step stronger in light, deep and opaque in dark, each
     keeping its text at 4.5:1 and APCA Lc 60 on every surface */
  --ok:#0c7c39; --ok-bg:#daf8df; --ok-mark:#00a23d; --warn:#9a4704; --warn-bg:#ffe5b8; --warn-mark:#f76700; --bad:#d0111c; --bad-bg:#fee4e1; --bad-mark:#f04438;
  --merge:#7c4cd4; --merge-bg:#f2ecfd; --add:#187633; --del:#c7212c;
  /* the core tag colours (owner, 21 Nov: "make it more saturated... look at the Attio chips"): a clearly coloured tint and the
     most saturated text of its hue that keeps 4.5:1 and APCA Lc 60 on it (and on every light surface) */
