  --shadow-toast:0 0 0 1px rgba(0,0,0,.03),0 4px 12px rgba(0,0,0,.08);
  --hl:#fdeb9a; --hl-ok:#d3f1df;
  /* Soft is plush: every corner is scaled by --rk, and larger still where the browser draws true squircles (below) */
  --rk:1.25;
  --r-card:calc(16px * var(--rk-l,var(--rk)));
