/* ---------- page shell ---------- */
.v2 *{box-sizing:border-box}
.v2 button,.v2 input,.v2 textarea,.v2 select{font:inherit;color:inherit}
.v2 button{background:none;border:0;padding:0;cursor:pointer}
/* one weight for emphasis: medium, never bold */
.v2 b,.v2 strong{font-weight:500}
.v2 :focus-visible{outline:2px solid var(--focus);outline-offset:2px;border-radius:calc(6px * var(--rk-s,var(--rk)))}
/* a control pressed with a pointer, or a button that got the focus back after a click (closePops), keeps no ring until a key
   that moves or acts is pressed; a ring drawn on the control's neighbour (a checkbox's box) goes with it */
.v2 [data-nofv]:focus-visible,.v2 [data-nofv]:focus-visible+*{outline:0}
/* a field shows the focus with its own edge, which steps up to --field-line-strong, so it never takes the ring as well */
.v2 :focus-visible:is(input:not([type="checkbox"],[type="radio"],[type="range"],[type="file"],[type="button"],[type="submit"],[type="reset"]),textarea,select,[contenteditable]:not([contenteditable="false"])){outline:0}
.v2.stage-in{width:100%;max-width:440px;min-width:0;position:relative;container-type:inline-size}
.v2.stage-in.wide{max-width:720px}

/* ---------- icons ---------- */
.v2 .i{width:16px;height:16px;flex:none;display:inline-block;vertical-align:-3px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.v2 .i.s{width:14px;height:14px}.v2 .i.xs{width:12px;height:12px}.v2 .i.l{width:18px;height:18px}
.v2 .brand{width:16px;height:16px;display:block;flex:none}
.v2 .flag{width:20px;height:15px;border-radius:var(--r-tiny,3px);object-fit:cover;display:block;flex:none;box-shadow:0 0 0 1px rgba(0,0,0,.08)}

/* ---------- primitives ---------- */
.v2 .mono{font-family:var(--mono)}
.v2 .sp{flex:1}
.v2 .num{font-variant-numeric:tabular-nums}
.v2 .muted{color:var(--muted)}.v2 .fg2{color:var(--fg2)}
.v2 .panel{background:var(--surface);border-radius:var(--r-card);box-shadow:var(--shadow);position:relative}
.v2 .ib{width:30px;height:30px;border-radius:50%;display:inline-grid;place-items:center;color:var(--fg2);transition:background var(--t-fast),color var(--t-fast),transform .15s}
@media (hover:hover) and (pointer:fine){.v2 .ib:hover{background:var(--row);color:var(--fg)}}
.v2 .ib.fill{background:var(--soft);box-shadow:var(--soft-ring)}
@media (hover:hover) and (pointer:fine){.v2 .ib.fill:hover{background:var(--soft-h)}}
.v2 .ib.on{background:var(--accent-bg);color:var(--accent-fg,var(--accent))}
.v2 .chip{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 var(--s-3);border-radius:var(--r-pill);font-size:13px;color:var(--fg2);background:var(--chip);white-space:nowrap;transition:background var(--t-fast),color var(--t-fast),box-shadow var(--t-fast)}
@media (hover:hover) and (pointer:fine){.v2 .chip:hover{background:var(--hover);color:var(--fg)}}
.v2 .chip.on{background:var(--surface);color:var(--fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--pick-on) 50%,transparent)}
.v2 .chip.sm{height:24px;padding:0 9px;font-size:12px}
/* a click never scales a button or its words (owner, 18 Nov); only Clean's ink primary presses, at .97 (in its own section) */
.v2 .pill{display:inline-flex;align-items:center;justify-content:center;gap:7px;height:32px;padding:0 14px;border-radius:var(--r-pill);font-size:13px;font-weight:500;white-space:nowrap;transition:background var(--t-fast),color var(--t-fast),opacity var(--t-fast),transform .15s}
/* the primary action is the accent, with --on-accent on it, so it follows the accent and stays readable in any colour */
