/* Matrix: each dot keeps its own beat, so the grid twinkles instead of sweeping */
.v2 .ths-mtx{display:grid;grid-template-columns:repeat(4,3px);gap:2px}
.v2 .ths-mtx i{display:block;width:3px;height:3px;border-radius:50%;background:currentColor;opacity:.2;animation:v2-thstw 2s var(--ease-io) infinite}
.v2 .ths-mtx i:nth-child(3n){animation-duration:2.6s}.v2 .ths-mtx i:nth-child(3n+1){animation-duration:1.7s}
.v2 .ths-mtx i:nth-child(1){animation-delay:-.1s}.v2 .ths-mtx i:nth-child(2){animation-delay:-.9s}.v2 .ths-mtx i:nth-child(3){animation-delay:-1.9s}.v2 .ths-mtx i:nth-child(4){animation-delay:-.4s}
.v2 .ths-mtx i:nth-child(5){animation-delay:-1.2s}.v2 .ths-mtx i:nth-child(6){animation-delay:-.2s}.v2 .ths-mtx i:nth-child(7){animation-delay:-1.6s}.v2 .ths-mtx i:nth-child(8){animation-delay:-.7s}
.v2 .ths-mtx i:nth-child(9){animation-delay:-.5s}.v2 .ths-mtx i:nth-child(10){animation-delay:-1.4s}.v2 .ths-mtx i:nth-child(11){animation-delay:-.05s}.v2 .ths-mtx i:nth-child(12){animation-delay:-1s}
.v2 .ths-mtx i:nth-child(13){animation-delay:-2.1s}.v2 .ths-mtx i:nth-child(14){animation-delay:-.8s}.v2 .ths-mtx i:nth-child(15){animation-delay:-1.3s}.v2 .ths-mtx i:nth-child(16){animation-delay:-.3s}
@keyframes v2-thstw{0%,100%{opacity:.2}45%,60%{opacity:1}}
/* Stack: three pages; the front one leaves and the others move up, each a third of the loop behind the next */
.v2 .ths-stk{position:relative;width:20px;height:20px}
.v2 .ths-stk i{position:absolute;left:3px;top:3px;width:11px;height:13px;border-radius:calc(2.5px * var(--rk-s,var(--rk)));background:var(--surface);box-shadow:inset 0 0 0 1.25px currentColor;color:color-mix(in srgb,var(--fg) 34%,transparent);animation:v2-thsstk 2.4s var(--ease-io) infinite}
.v2 .ths-stk i:nth-child(1){translate:6px -3px;opacity:.6;z-index:1}
.v2 .ths-stk i:nth-child(2){translate:3px 0;opacity:.85;z-index:2;animation-delay:-.8s}
.v2 .ths-stk i:nth-child(3){translate:0 3px;z-index:3;color:var(--accent-mark,var(--accent));animation-delay:-1.6s}
@keyframes v2-thsstk{0%{translate:6px -3px;opacity:.6;z-index:1;color:color-mix(in srgb,var(--fg) 34%,transparent)}25%{translate:3px 0;opacity:.85;z-index:2;color:color-mix(in srgb,var(--fg) 34%,transparent)}50%,66%{translate:0 3px;opacity:1;z-index:3;color:var(--accent-mark,var(--accent))}80%{translate:-5px 6px;opacity:0;z-index:3;color:var(--accent-mark,var(--accent))}81%{translate:6px -3px;opacity:0;z-index:1;color:color-mix(in srgb,var(--fg) 34%,transparent)}100%{translate:6px -3px;opacity:.6;z-index:1;color:color-mix(in srgb,var(--fg) 34%,transparent)}}
/* six choices fit under the demo on a phone */
@container (max-width:380px){.v2 .ths-dm>.demo .seg2 button{padding:0 7px;font-size:12px}}
/* reduced motion: every mark holds a pose that still reads (the orbit's light and tail, a circle, a lit column, the first
   words, a lit diamond, a stack), the caret stays lit and the sweep goes */
@media (prefers-reduced-motion:reduce){.v2 .ths-mk *,.v2 .ths-car{animation:none!important}.v2 .ths-dg .p{opacity:1}.v2 .ths-mtx i:is(:nth-child(2),:nth-child(5),:nth-child(7),:nth-child(10),:nth-child(12),:nth-child(15)){opacity:1}}
/* Blueprint: a square tile with a hairline, square dots, marks that tick in steps and a block caret */
:root:not([data-style="soft"],[data-style="clean"]) .v2 .ths-mk{background:var(--surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--rail) 50%,transparent)}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .ths-dg i{border-radius:0}
