.v2 .rtr{width:100%;padding:6px}
.v2 .rtr-h{display:flex;align-items:center;gap:10px;width:100%;padding:10px var(--s-3);border-radius:var(--r-in);font-size:13.5px;transition:background .2s}
@media (hover:hover) and (pointer:fine){.v2 .rtr-h:hover{background:var(--row)}}
