@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .rtr-h:hover{background:none}}
:root[data-style="clean"] .v2 .rtr-h:focus-visible{outline-offset:-2px;border-radius:var(--r-card)}
/* the head's 14px mark sits centred on the steps' 16px marks, and its words start where theirs do (44px in) */
:root[data-style="clean"] .v2 .rtr-mark{color:var(--fg);margin:0 1px}
:root[data-style="clean"] .v2 .rtr-title{font-weight:500}
:root[data-style="clean"] .v2 .rtr-title:not(.shim){color:var(--fg)}
:root[data-style="clean"] .v2 .rtr-time{font-variant-numeric:tabular-nums}
:root[data-style="clean"] .v2 .rtr-chev{width:14px;height:14px;border-radius:50%;box-shadow:0 0 0 7px transparent;transition:transform .4s var(--ease),background-color var(--t-fast) var(--ease),box-shadow var(--t-fast) var(--ease),color var(--t-fast) var(--ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .rtr-h:hover .rtr-chev{background:var(--row);box-shadow:0 0 0 7px var(--row);color:var(--fg)}}
:root[data-style="clean"] .v2 .rtr-body{padding:10px 16px;border-top:1px solid var(--line)}
