:root[data-style="clean"] .v2 .rtr-body[data-v="plan"] .rtr-li:not(:last-child)::before{background:var(--line) linear-gradient(var(--line-strong),var(--line-strong)) no-repeat 0 0/100% 0}
:root[data-style="clean"] .v2 .rtr-body[data-v="plan"] .rtr-li[data-s="done"]:not(:last-child)::before{background-size:100% 100%}
/* the marks */
