:root[data-style="clean"] .v2 .rtr-m{display:grid;place-items:center;width:16px;height:16px;box-sizing:border-box;border-radius:50%}
:root[data-style="clean"] .v2 [data-s="next"]>.g>.rtr-m{box-shadow:inset 0 0 0 1px var(--line-strong)}
:root[data-style="clean"] .v2 [data-s="now"]>.g>.rtr-m{border:1.5px solid var(--line);border-top-color:var(--fg);animation:v2-rot .9s linear infinite}
