:root[data-style="clean"] .v2 .rtr-src{gap:8px}
:root[data-style="clean"] .v2 .rtr-body[data-v="edits"] .g{color:var(--muted)}
:root[data-style="clean"] .v2 .rtr-edit{border-radius:var(--r-box);margin:4px 0 8px;padding:8px 12px;line-height:20px}
:root[data-style="clean"] .v2 .rtr-body>.rtr-edit:last-child,:root[data-style="clean"] .v2 .rtr-body>:last-child>.rtr-edit:last-child{margin-bottom:6px}
