.v2 .trv-hi{width:32px;height:32px;display:grid;place-items:center;flex:none;border-radius:calc(9px * var(--rk-m,var(--rk)));color:var(--fg2);background:var(--chip)}
.v2 .trv-ht{flex:1;display:flex;flex-direction:column;min-width:0}
.v2 .trv-ht b{font-weight:500;font-size:14px;line-height:20px}
.v2 .trv-st{font-size:12.5px;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* the run's totals: its tokens, quiet, then its time over the Time column */
.v2 .trv-tt{flex:none;margin-right:-4px;font-size:12.5px;white-space:nowrap}
.v2 .trv-tot{font-size:14px;font-weight:500;flex:none}
/* the key: each kind with its colour and how many of its spans have started */
.v2 .trv-lg{display:flex;flex-wrap:wrap;gap:2px var(--s-3);padding:8px 0 12px 44px;font-size:12px;color:var(--muted)}
.v2 .trv-lg span{display:inline-flex;align-items:center;gap:5px;white-space:nowrap;transition:color .3s}
.v2 .trv-lg i{width:8px;height:8px;border-radius:var(--r-tiny,2px);background:var(--k);flex:none}
.v2 .trv-lg b{font-weight:500;color:var(--fg2)}
.v2 .trv-lg span.z{color:var(--dis)}.v2 .trv-lg span.z b{color:inherit}.v2 .trv-lg span.z i{opacity:.45}
.v2 .trv-ax,.v2 .trv-r{display:grid;grid-template-columns:var(--cols);align-items:center;gap:var(--s-2);padding:0 8px 0 0}
.v2 .trv-ax{height:30px;border-top:1px solid color-mix(in srgb,var(--line) 50%,transparent);font-size:12px;color:var(--muted)}
.v2 .trv-ax>span:first-child{padding-left:44px}
.v2 .trv-tk,.v2 .trv-ms{text-align:right;white-space:nowrap}
.v2 .trv-sc{position:relative;height:18px}
.v2 .trv-sc span{position:absolute;top:0;transform:translateX(-50%);font-size:12px}
.v2 .trv-sc span:first-child{transform:none}
