.v2 .trv-r{width:100%;min-height:32px;border-radius:calc(10px * var(--rk-m,var(--rk)));font-size:13px;text-align:left;transition:background .16s}
.v2 .trv-r[aria-expanded="true"]{background:var(--row)}
@media (hover:hover) and (pointer:fine){.v2 .trv-r:hover{background:var(--row)}}
