:root[data-style="clean"] .v2 .trv-io code{background:var(--surface);box-shadow:inset 0 0 0 1px var(--hair)}
/* ---------- Run cost ---------- */
/* the card's content sits 16px in from every edge (owner, 18 Nov); nothing in it grows or shrinks when it is pressed */
.v2 .rc{padding:var(--s-4)}
.v2 .rc :is(.pill,.ib):active{transform:none}
.v2 .rc-h{display:flex;align-items:center;justify-content:space-between;font-size:12.5px}
