.v2 .rc-track{position:relative;height:6px;border-radius:var(--r-xs);background:var(--rail);margin:14px 0 var(--s-4)}
.v2 .rc-fill{height:100%;width:0;border-radius:var(--r-xs);background:var(--accent-mark,var(--accent));transition:background .4s}
