:root[data-style="clean"] .v2 .rc-f{margin:11px -16px 0;padding:8px 16px;border-top:1px solid var(--line);background:var(--strip);border-radius:0 0 var(--r-card) var(--r-card)}
:root[data-style="clean"] .v2 .rc-cap-t{height:28px;padding:0 10px 0 8px;border-radius:var(--r-pill);gap:8px;transition:background-color var(--t-fast) var(--ease),color var(--t-fast) var(--ease)}
