:root[data-style="clean"] .v2 .tsk-c .g{width:20px;height:20px;margin-top:calc(8.775px - 10px);background:none!important;color:var(--fg2)!important}
:root[data-style="clean"] .v2 .tsk-c .g .i{width:20px;height:20px}
