.v2 .aln-lane[data-s="done"] .aln-av{background:var(--cb);color:var(--c)}
.v2 .aln-who{min-width:0}
.v2 .aln-n{display:block;font-weight:500;font-size:13.5px}
.v2 .aln-a{display:block;font-size:12.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .aln-a.live{color:var(--fg2)}
/* the track: one part a step. Finished parts are solid, the one in hand fills as the agent works, with a light running along it */
.v2 .aln-tr{display:flex;gap:3px}
.v2 .aln-tr i{flex:1;height:10px;border-radius:var(--r-tiny,5px);background:color-mix(in srgb,var(--cm) 16%,var(--surface));position:relative;overflow:hidden}
.v2 .aln-tr i::after{content:"";position:absolute;inset:0;border-radius:inherit;background:var(--cm);transform:scaleX(var(--p,0));transform-origin:left;transition:transform .25s linear}
.v2 .aln-tr i.on::after{transform:scaleX(1);transition:transform .5s var(--ease)}
