/* given no step progress, the part in hand fills part way and keeps its light */
.v2 .aln-tr i.run.ind::after{transform:scaleX(.6);transition:transform 2.4s var(--ease)}
@keyframes v2-alnsheen{from{background-position:100% 0}to{background-position:-150% 0}}
.v2 .aln-st{min-width:92px;display:flex;justify-content:flex-end}
.v2 .aln-tg{background:var(--cb);color:var(--c)}
.v2 .aln-tg .spin{width:9px;height:9px}
.v2 .aln-det{padding:0 10px 10px 56px;font-size:12.5px;color:var(--fg2)}
