  .v2 .aln-lane::before{top:48px}
  .v2 .aln-ct{display:none}
  .v2 .aln-m{margin-right:auto}
}
@media (max-width:400px){.v2 .aln-ic{display:none}}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .aln-rows>*::before,:root:not([data-style="soft"],[data-style="clean"]) .v2 .aln-lane::after{width:1px;left:26.5px;background:repeating-linear-gradient(var(--rail) 0 3px,transparent 3px 6px)}
