.v2 .aln-sw-key .done{background:var(--kc)}
.v2 .aln-sw-key .wait{background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--kc) 30%,transparent) 0 1px,transparent 1px 3px)}
