/* ---------- Agent run timeline ---------- */
/* each kind of step has a hue: --k paints its bar, --kt its text and icon, --kb the icon's tint. The model is purple, tools
   are teal and apps orange, each app with its own mark. The playhead runs in the accent with the time on it, and the lanes it
   has passed take a faint wash; once the run is done it stops at the finish and turns green */
.v2 .art{padding:var(--s-4);--lab:176px;--dur:44px}
/* the head has a neutral mark in a tile as big as the steps' icons, so the steps' icons sit in its column and their names
   start where the title starts (owner, 18 Nov); the key lines up with the title's words too */
.v2 .art-h{display:flex;align-items:center;gap:var(--s-2)}
.v2 .art-hi{width:22px;height:22px;border-radius:calc(7px * var(--rk-m,var(--rk)));display:grid;place-items:center;flex:none;background:var(--chip);color:var(--fg2)}
.v2 .art-hd{flex:1;min-width:0}
.v2 .art-t{font-weight:500;line-height:18px}
.v2 .art-s{font-size:12.5px;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .art-s.sw{display:block}
.v2 .art-tag{flex:none;transition:background .3s,color .3s}
.v2 .art-tag .spin{width:9px;height:9px}
.v2 .art.live .art-tag{background:var(--accent-bg);color:var(--accent-fg,var(--fg))}
/* the key: how long each kind has run so far */
.v2 .art-key{display:flex;flex-wrap:wrap;gap:2px var(--s-4);margin-top:10px;padding-left:30px;font-size:12px;color:var(--muted)}
.v2 .art-key span{display:inline-flex;align-items:center;gap:6px;white-space:nowrap}
.v2 .art-key i{width:8px;height:8px;border-radius:var(--r-tiny,2px);background:var(--k);flex:none}
.v2 .art-key b{font-weight:500;color:var(--fg2)}
.v2 .art-grid{position:relative;margin-top:var(--s-3)}
.v2 .art-axis,.v2 .art-row{display:grid;grid-template-columns:var(--lab) minmax(0,1fr) var(--dur);align-items:center}
.v2 .art-axis{height:20px;font-size:11px;color:var(--muted)}
.v2 .art-ticks{position:relative;height:16px}
.v2 .art-ticks span{position:absolute;top:0;transform:translateX(-50%);transition:opacity .2s}
.v2 .art-ticks span:first-child{transform:none}
.v2 .art-ticks span:last-child{transform:translateX(-100%)}
.v2 .art-ticks span.hid{opacity:0}
.v2 .art-rows{position:relative}
.v2 .art-row{height:32px}
.v2 .art-lab{display:flex;align-items:center;gap:var(--s-2);min-width:0;padding-right:var(--s-3);font-size:12.5px;color:var(--fg2);white-space:nowrap;transition:color .3s}
.v2 .art-lab .t{min-width:0;overflow:hidden;text-overflow:ellipsis}
.v2 .art-lab .tag{flex:none}
.v2 .art-ic{--ring:0 0 0 0 transparent;width:22px;height:22px;border-radius:calc(7px * var(--rk-m,var(--rk)));display:grid;place-items:center;flex:none;background:var(--kb);color:var(--kt);box-shadow:var(--ring);transition:opacity .3s}
.v2 .art-ic .brand{width:13px;height:13px}
/* an app's own mark sits on a plain tile */
.v2 .art-row[data-k="app"] .art-ic{--ring:inset 0 0 0 1px color-mix(in srgb,var(--rail) 50%,transparent);background:var(--surface);color:var(--fg)}
/* a step that hasn't started waits quietly; the one at work breathes a ring of its hue round its icon */
.v2 .art-row[data-s="wait"] .art-lab{color:var(--muted)}
.v2 .art-row[data-s="wait"] .art-ic{opacity:.45}
.v2 .art-row[data-s="run"] .art-lab{color:var(--fg)}
.v2 .art-row[data-s="run"] .art-ic{animation:v2-artbreathe 1.8s var(--ease-io) infinite}
@keyframes v2-artbreathe{0%,100%{box-shadow:var(--ring),0 0 0 0 color-mix(in srgb,var(--fg) 0%,transparent)}50%{box-shadow:var(--ring),0 0 0 3px color-mix(in srgb,var(--fg) 10%,transparent)}}
.v2 .art-row.bump .art-ic{animation:v2-artpop .45s var(--ease)}
@keyframes v2-artpop{40%{transform:scale(1.14)}}
/* the lanes: quarter lines at half strength, a bar for each step */
