.v2 .art-bar{position:absolute;top:9px;height:14px;width:0;border-radius:var(--r-tiny,5px);background:linear-gradient(90deg,var(--k),color-mix(in oklab,var(--k) 82%,#fff));cursor:default;transition:filter .2s}
@media (hover:hover) and (pointer:fine){.v2 .art-bar:hover{filter:brightness(1.08) saturate(1.1)}}
