.v2 .art-row[data-s="run"] .art-bar{background:linear-gradient(100deg,transparent 30%,rgba(255,255,255,.42) 46%,transparent 62%) 0 0/250% 100% no-repeat,var(--k);animation:v2-artsheen 1.3s linear infinite}
.v2 .art-bar i{display:none;position:absolute;right:-1px;top:-3px;bottom:-3px;width:2px;border-radius:1px;background:var(--k);box-shadow:none}
.v2 .art-row[data-s="run"] .art-bar i{display:block}
@keyframes v2-artsheen{from{background-position:120% 0,0 0}to{background-position:-120% 0,0 0}}
.v2 .art-row[data-s="fail"] .art-bar{background:repeating-linear-gradient(135deg,var(--c5) 0 3px,color-mix(in srgb,var(--c5) 45%,var(--surface)) 3px 6px)}
/* a retry hangs off the end of the step that failed */
.v2 .art-link{position:absolute;top:-9px;height:25px;min-width:6px;border-left:1px dashed var(--warn-mark);border-bottom:1px dashed var(--warn-mark);pointer-events:none;display:none}
