/* how long each step took, counting while it runs */
.v2 .art-d{font-size:12px;color:var(--muted);text-align:right;white-space:nowrap}
.v2 .art-row[data-s="run"] .art-d{color:var(--kt)}
.v2 .art-row[data-s="done"] .art-d{color:var(--fg2)}
.v2 .art-row[data-s="fail"] .art-d{color:var(--bad)}
/* the playhead, with the time on the axis, and the wash over what it has passed */
.v2 .art-past{position:absolute;top:20px;bottom:0;left:var(--lab);width:calc((100% - var(--lab) - var(--dur)) * var(--p,0));background:linear-gradient(90deg,transparent,var(--sel));pointer-events:none;opacity:0;transition:opacity .5s}
.v2 .art.live .art-past{opacity:1}
.v2 .art-head{position:absolute;top:2px;bottom:0;left:calc(var(--lab) + (100% - var(--lab) - var(--dur)) * var(--p,0));width:0;pointer-events:none;opacity:0;transition:opacity .4s}
.v2 .art.live .art-head,.v2 .art.fin .art-head{opacity:1}
.v2 .art-head i{position:absolute;top:16px;bottom:0;left:-.75px;width:1.5px;border-radius:1px;background:var(--accent-mark,var(--accent));transition:background .4s}
.v2 .art-now{position:absolute;top:0;left:0;transform:translateX(-50%);display:inline-flex;align-items:center;gap:3px;height:16px;padding:0 5px;border-radius:var(--r-tiny,5px);background:var(--accent);color:var(--on-accent,#fff);font-size:11px;font-weight:500;line-height:1;white-space:nowrap;transition:background .4s,color .4s}
