.v2 .art.fin .art-head i{background:var(--ok-mark)}
.v2 .art.fin .art-now{background:var(--ok-bg);color:var(--ok)}
.v2 .art-f{display:flex;flex-wrap:wrap;gap:var(--s-2) var(--s-5);margin-top:var(--s-3);padding-top:var(--s-3);border-top:1px solid color-mix(in srgb,var(--line) 50%,transparent);font-size:12.5px;line-height:16px}
/* each figure's icon is centred in the steps' icon column (22px) and its words start on their names' column */
.v2 .art-f>span{display:inline-flex;align-items:center;gap:var(--s-2);white-space:nowrap}
.v2 .art-f>span>svg{box-sizing:content-box;padding:0 5px}
.v2 .art-f b{color:var(--fg);font-weight:500}
@media (max-width:600px){.v2 .art{--lab:112px;--dur:38px}.v2 .art-lab{gap:6px;padding-right:var(--s-2)}.v2 .art-lab .tag{display:none}.v2 .art-f{gap:var(--s-2) var(--s-4)}
  /* the head's tile, the key and the figures keep the steps' closer columns */
  .v2 .art-h,.v2 .art-f>span{gap:6px}.v2 .art-key{padding-left:28px}}
/* a phone: each step's name sits on its own line above its bar, so it is read in full; the bars take the whole width */
@media (max-width:480px){
  .v2 .art{--lab:0px}
  .v2 .art-row{height:auto;grid-template-rows:auto 22px;row-gap:2px;padding:5px 0 3px}
  .v2 .art-row .art-lab{grid-column:1/-1;grid-row:1;padding-right:0}
  .v2 .art-row .art-lab .t{white-space:normal;overflow:visible}
  .v2 .art-row .art-lane{grid-column:2;grid-row:2;height:22px}
  .v2 .art-row .art-d{grid-column:3;grid-row:2}
  .v2 .art-bar{top:4px}
  .v2 .art-ic,.v2 .art-hi{width:20px;height:20px}
  .v2 .art-key{padding-left:26px}
  .v2 .art-f>span>svg{padding:0 4px}
  .v2 .art-link{top:-35px;height:39px}
}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .art-ic{--ring:inset 0 0 0 1px color-mix(in srgb,var(--k) 35%,transparent)}
