.v2 .cite.on{background:var(--accent-bg);color:var(--accent-fg,var(--accent))}
@media (hover:hover) and (pointer:fine){.v2 .cite:hover{background:var(--accent-bg);color:var(--accent-fg,var(--accent))}}
