.v2 .lva-src{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--muted)}
.v2 .lva-sb{display:inline-flex;align-items:center;gap:var(--s-2);height:28px;padding:0 9px 0 5px;border-radius:var(--r-pill);color:var(--fg2);transition:background .2s,color .2s}
