:root[data-style="clean"] .v2 :is(.lva-tb,.lva-sb,.lva-s,.lva-fu button){transition:background-color var(--t-fast) var(--ease),color var(--t-fast) var(--ease),box-shadow var(--t-fast) var(--ease)}
/* ---------- Composer ---------- */
.v2 .cpx{display:flex;flex-direction:column;justify-content:flex-end;gap:14px;overflow-anchor:none;container-type:inline-size}
/* neither the composer nor the box it sits in anchors the page's scroll, so the page stays put as the thread grows and clears */
.v2.stage-in:has(>.cpx){overflow-anchor:none}
/* no room is kept for the conversation (owner, 18 Nov): the thread and the box grow together (grow()) and stay centred in the
   stage. Its menus open over it from their buttons, down when there is room and up when there isn't, and the composer never
   moves for them (the visitor's clicks never move it). grow() must not clip the menus */
.v2 .cpx.growing{overflow:visible}
.v2 .cpx-thread{display:flex;flex-direction:column;gap:var(--s-3)}
.v2 .cpx-thread:empty{display:none}
/* a message that is only attachments (owner, 19 Nov): the files sit on their own at the thread's right edge, as a chat app shows
   them, never in an empty bubble; with words they stay in the bubble, above the words */
.v2 .cpx-files{align-self:flex-end;max-width:85%;display:flex;flex-wrap:wrap;justify-content:flex-end;gap:6px}
.v2 .cpx-ag{font-size:14px;color:var(--fg2);display:flex;gap:var(--s-2);align-items:center}
/* the composer is a component, not a field: a quiet hairline and a soft shadow, the same while you type in it */
.v2 .cpx-box{position:relative;background:var(--surface);border-radius:var(--r-box);box-shadow:var(--shadow);transition:box-shadow var(--t-fast)}
@supports (corner-shape:squircle){.v2 .cpx-box{corner-shape:squircle;border-radius:var(--r-box-sq)}}
/* everything in the box sits 16px from its edges (owner, 18 Nov): the attachments, the text, Send's edge and the dictation
   line; the attach button's glyph lines up with the text, and the toolbar's controls share one centre line */
.v2 .cpx-att{display:flex;gap:6px;flex-wrap:wrap;padding:16px 16px 0}
.v2 .cpx-att:empty{display:none}
.v2 .cpx-att .fchip{transition:color .32s,background .32s}
/* a chip never runs past the box on a narrow card: it shrinks to the row and its name trims */
.v2 .cpx-att .fchip{max-width:100%;min-width:0}
.v2 .cpx-att .fchip .n{min-width:0;overflow:hidden;text-overflow:ellipsis}
.v2 .cpx-att .fchip .x,.v2 .cpx-att .fchip .rt{display:grid;place-items:center;width:18px;height:18px;border-radius:50%;margin-right:-4px;color:var(--muted)}
@media (hover:hover) and (pointer:fine){.v2 .cpx-att .fchip .x:hover,.v2 .cpx-att .fchip .rt:hover{background:var(--row);color:var(--fg)}}
.v2 .cpx-att .fchip .spin{width:10px;height:10px}
.v2 .cpx-att .fchip.ld{color:var(--muted)}
.v2 .cpx-att .fchip.err{color:var(--bad);background:var(--bad-bg);box-shadow:none}
.v2 .cpx-att .fchip.err .rt{color:var(--bad)}
.v2 .cpx-ta{display:block;width:100%;border:0;outline:0;resize:none;background:none;color:var(--fg);font:inherit;font-size:14px;line-height:1.5;padding:14px 16px var(--s-1);min-height:54px;max-height:160px;transition:color .32s}
.v2 .cpx-ta::placeholder{color:var(--muted)}
.v2 .cpx-box[data-mode="voice"] .cpx-ta{color:var(--fg2)}
.v2 .cpx-rows{display:grid;padding:4px 16px 16px}
.v2 .cpx-bar,.v2 .cpx-voice{grid-area:1/1;display:flex;align-items:center;gap:var(--s-1);min-width:0;transition:opacity .32s var(--ease),transform .42s var(--ease)}
.v2 .cpx-voice{opacity:0;transform:translateY(6px);pointer-events:none;visibility:hidden;transition:opacity .32s var(--ease),transform .42s var(--ease),visibility 0s .32s}
.v2 .cpx-box[data-mode="voice"] .cpx-bar{opacity:0;transform:translateY(-6px);pointer-events:none}
.v2 .cpx-box[data-mode="voice"] .cpx-voice{opacity:1;transform:none;pointer-events:auto;visibility:visible;transition-delay:0s}
.v2 .cpx-bar>.ib{width:32px;height:32px;flex:none}
.v2 .cpx-bar>.cpx-add{margin-left:-9px}
.v2 .cpx-add[aria-expanded="true"]{background:var(--chip);color:var(--fg)}
.v2 .cpx-bar .chip{height:32px;padding:0 10px;gap:6px;background:none;min-width:0;font-size:13px;color:var(--fg2)}
.v2 .cpx-bar .chip[aria-expanded="true"]{background:var(--row);color:var(--fg)}
@media (hover:hover) and (pointer:fine){.v2 .cpx-bar .chip:hover{background:var(--row);color:var(--fg)}}
.v2 .cpx-bar .chip>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.v2 .cpx-bar .chip>svg:last-child{color:var(--muted)}
/* a narrow box: the context and mode chips keep only their icon (the name stays for screen readers, and in the tooltip) */
@container (max-width:400px){.v2 .cpx-bar .chip{padding:0 8px}.v2 .cpx-bar .chip>span{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.v2 .cpx-bar .chip>svg:last-child{display:none}}
.v2 .cpx-send{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:var(--accent);color:var(--on-accent,#fff);flex:none;transition:opacity .32s,transform .16s,background .16s}
@media (hover:hover) and (pointer:fine){.v2 .cpx-send:hover{background:var(--accent-2)}}
.v2 .cpx-send[disabled]{opacity:1;cursor:not-allowed;background:var(--dis-hatch),var(--dis-fill);color:var(--dis);box-shadow:var(--soft-ring)}
/* dictation: a red dot and a clock while it listens, the words arriving in the box, then Cancel or Done */
.v2 .cpx-rec{display:inline-flex;align-items:center;gap:var(--s-2);font-size:13px;color:var(--fg)}
