@keyframes v2-cpxrec{50%{opacity:.35}}
.v2 .cpx-tm{font-size:13px;margin-left:var(--s-1)}
.v2 .cpx-voice .pill{flex:none}
.v2 .pp-plus,.v2 .pp-ctx,.v2 .pp-mode{width:264px}
.v2 .cpx-bar>.cpx-send{flex:none}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink Send alone presses */
.v2 .cpx :is(.ib,.pill,.chip):active,:root[data-style="clean"] .v2 .cpx .ib:active{transform:none}
@media (max-width:480px){.v2 .cpx-bar .cpx-ctx>span{max-width:88px}}
/* Clean (owner, 18 Nov): the box takes the card's 22px round corners and its toolbar's controls are 28px. Send is the ink
   button. A file that failed keeps the chip's white with its words and mark in red, no red fill */
:root[data-style="clean"] .v2 .cpx-box{border-radius:var(--r-card)}
:root[data-style="clean"] .v2 .cpx-att{gap:4px}
:root[data-style="clean"] .v2 .cpx-bar>.cpx-add{margin-left:-7px}
:root[data-style="clean"] .v2 .cpx-bar>.ib{width:28px;height:28px}
