.v2 .rte-b:is([aria-pressed="true"],.on){background:var(--accent-bg);color:var(--accent-fg)}
.v2 .rte-b:disabled,.v2 .rte-ai:disabled{opacity:1;cursor:not-allowed;background:none;color:var(--dis)}
.v2 .rte-sep{width:1px;height:16px;margin:0 5px;flex:none;background:var(--line)}
.v2 .rte-ai{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 11px 0 9px;flex:none;border-radius:var(--r-pill);font-size:13px;color:var(--fg);transition:background var(--t-fast),color var(--t-fast)}
.v2 .rte-ai .i{color:var(--accent-fg)}
.v2 .rte-ai[aria-expanded="true"]{background:var(--row)}
@media (hover:hover) and (pointer:fine){.v2 .rte-ai:hover{background:var(--row)}}
.v2 .rte-ai:disabled .i{color:inherit}
/* the text: one quiet size, a heading set apart by weight and room rather than size, and nothing heavier than medium */
.v2 .rte-body{position:relative;height:256px;overflow-y:auto;padding:14px var(--s-4) var(--s-4);outline:0;font-size:14px;line-height:1.65;color:var(--fg);white-space:pre-wrap;overflow-wrap:break-word;caret-color:var(--accent-fg);cursor:text}
.v2 .rte-body>*{margin:0;padding:0}
