.v2 .rte-body code{font-family:var(--mono);font-size:12.5px;padding:1px var(--s-1);border-radius:var(--r-tiny,5px);background:var(--chip);color:var(--fg)}
.v2 .rte-body :is(ul,ol){padding-left:22px}
