.v2 .atx-dm>.dm-main>*{align-self:stretch}
.v2 .atx-dm .atx-list{min-height:164.5px}
/* in Clean the card grows with its files instead (owner, 17 Nov: no room kept for a later state) */
:root[data-style="clean"] .v2 .atx-dm .atx-list{min-height:0}
/* what both designs share: a clear file input over the control that opens it, and a grey picture of what is in each file
   (a page for a PDF, frames for a Figma file, a grid for a sheet, a scene for an image), its kind in the site's grey tag */
.v2 .atx-pick{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer;font-size:0}
.v2 .atx-art{display:block;width:100%;height:100%}
.v2 .atx-art .pg{fill:var(--surface)}
.v2 .atx-art .ln{fill:color-mix(in srgb,var(--fg) 14%,transparent)}
.v2 .atx-art .ac{fill:color-mix(in srgb,var(--fg) 26%,transparent)}
.v2 .atx-art .ac2{fill:color-mix(in srgb,var(--fg) 9%,transparent)}
.v2 .atx-art .ed{fill:none;stroke:color-mix(in srgb,var(--fg) 12%,transparent);stroke-width:1}
.v2 .atx-art .gd{stroke:color-mix(in srgb,var(--fg) 12%,transparent);stroke-width:1}
@keyframes v2-atxpopin{from{opacity:0;transform:translateY(10px) scale(.92)}}
.v2 .atx-popin{animation:v2-atxpopin .5s var(--ease) backwards}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .atx-popin{animation:v2-bpin .3s var(--ease) backwards}

/* Composer: files ride in the message box as previews that fill from the foot as they upload. Empty, the tray shows a line
   drawing of files dropping into a tray, in the site's greys with the accent on the top sheet. Dropped files land in place
   one after another and settle with a small bounce; the box gives a little as they hit it */
.v2 .atx-cmp{display:flex;flex-direction:column}
.v2 .atx-cmp-box{position:relative;display:flex;flex-direction:column;gap:var(--s-1);padding:var(--s-2);border-radius:var(--r-box);background:var(--surface);box-shadow:var(--shadow);transition:box-shadow .3s}
@supports (corner-shape:squircle){.v2 .atx-cmp-box{corner-shape:squircle;border-radius:var(--r-box-sq)}}
.v2 .atx-cmp-box.thud{animation:v2-atxcmpthud .42s var(--ease) .44s}
@keyframes v2-atxcmpthud{35%{transform:translateY(1.5px) scale(.996)}}
.v2 .atx-cmp-tray{position:relative;min-height:126.5px}
.v2 .atx-cmp-list{position:relative;display:flex;gap:var(--s-2);min-height:126.5px;padding:var(--s-2);overflow-x:auto;scrollbar-width:none}
.v2 .atx-cmp-list::-webkit-scrollbar{display:none}
/* the empty tray: the drawing (in Soft, a small file card) and a short line, inside a dashed drop target at half strength */
.v2 .atx-cmp-empty{position:absolute;inset:0 0 4px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:var(--s-2);text-align:center;padding:0 var(--s-4);border-radius:var(--r-in);border:1px dashed color-mix(in srgb,var(--faint) 50%,transparent);pointer-events:none;transition:opacity .26s var(--ease),transform .3s var(--ease)}
.v2 .atx-cmp-empty.out{opacity:0;transform:scale(.98)}
.v2 .atx-cmp-empty p{display:flex;flex-direction:column;align-items:center;margin:0;font-size:12.5px;line-height:1.45;color:var(--muted)}
.v2 .atx-cmp-empty b{font-weight:500;font-size:13px;color:var(--fg)}
.v2 .atx-cmp-art{flex:none;width:84px;height:56px;overflow:visible}
/* Soft's empty tray shows a small file card instead of the line drawing (owner, 18 Nov: "more similar to clean but softer"):
   the drawing's size, Soft's plush corners and soft outside shadow, three rows of a tile and a line in greys that fade
   downwards, and the first file's tile in the accent's tint with its line in the accent's mark. Blueprint keeps the drawing */
.v2 .atx-cmp-empty .atx-cmp-art{display:none}
.v2 .atx-cmp-sk{flex:none;display:flex;flex-direction:column;justify-content:center;gap:7px;width:84px;height:56px;padding:0 12px;border-radius:calc(9px * var(--rk));background:var(--surface);box-shadow:var(--shadow)}
.v2 .atx-cmp-sk .r{display:flex;align-items:center;gap:6px}
.v2 .atx-cmp-sk i{display:block;flex:none;height:4px;border-radius:calc(2px * var(--rk));background:color-mix(in srgb,var(--fg) 9%,var(--surface))}
.v2 .atx-cmp-sk .t{width:8px;height:8px;border-radius:calc(2.5px * var(--rk))}
.v2 .atx-cmp-sk .l{width:36px}
.v2 .atx-cmp-sk .r:nth-child(2) .l{width:30px}
.v2 .atx-cmp-sk .r:nth-child(3) i{background:color-mix(in srgb,var(--fg) 5%,var(--surface))}
.v2 .atx-cmp-sk .r:nth-child(3) .l{width:24px}
.v2 .atx-cmp-sk .r:first-child .t{background:var(--accent-bg)}
.v2 .atx-cmp-sk .r:first-child .l{background:color-mix(in srgb,var(--accent-mark,var(--accent)) 55%,var(--surface))}
@supports (corner-shape:squircle){.v2 .atx-cmp-sk,.v2 .atx-cmp-sk i{corner-shape:squircle}}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .atx-cmp-empty .atx-cmp-art{display:block}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .atx-cmp-sk{display:none}
.v2 .atx-cmp-art *{vector-effect:non-scaling-stroke}
.v2 .atx-cmp-art .gd{fill:none;stroke:color-mix(in srgb,var(--faint) 55%,transparent);stroke-width:1;stroke-dasharray:2 3}
.v2 .atx-cmp-art .pl{fill:var(--surface)}
.v2 .atx-cmp-art .tr-f{fill:var(--wash)}
.v2 .atx-cmp-art .sh.b .pl{fill:color-mix(in srgb,var(--accent-mark,var(--accent)) 7%,var(--surface))}
.v2 .atx-cmp-art .ln{fill:none;stroke:color-mix(in srgb,var(--line-strong) 55%,var(--surface));stroke-width:1;stroke-linejoin:round;stroke-linecap:round}
.v2 .atx-cmp-art .tx{stroke:color-mix(in srgb,var(--field-line-strong) 60%,var(--surface))}
.v2 .atx-cmp-art .ac{stroke:color-mix(in srgb,var(--accent-mark) 75%,var(--surface))}
/* the sheets hover over the tray, the top one a little higher, and drop into it as files land */
.v2 .atx-cmp-art .sh{animation:v2-atxcmpfloat 3.2s var(--ease-io) infinite;transition:transform .3s var(--ease),opacity .26s}
.v2 .atx-cmp-art .sh.b{animation-delay:-1.1s}
@keyframes v2-atxcmpfloat{50%{transform:translateY(-2px)}}
.v2 .atx-cmp-empty.out .sh{animation:none;transform:translateY(9px);opacity:0}
.v2 .atx-cmp-empty.out .sh.b{transform:translateY(16px)}
/* a file: its picture is veiled until it is up, the veil drawn back from the foot as it goes; a light passes over it while
   the agent reads it */
.v2 .atx-cmp-it{position:relative;flex:none;width:84px;display:flex;flex-direction:column;gap:var(--s-1);border-radius:var(--r-in);text-align:left;cursor:grab;touch-action:none;transition:transform .35s var(--ease)}
.v2 .atx-cmp-it:focus-visible{outline-offset:2px;border-radius:var(--r-in)}
.v2 .atx-cmp-it.drag{cursor:grabbing;z-index:3;transition:none}
.v2 .atx-cmp-it.drag .atx-cmp-th{box-shadow:var(--shadow-pop);transform:rotate(-2deg) scale(1.04)}
/* landing: each file comes down from above, a little turned (--r), touches down, lifts a hair and settles */
.v2 .atx-cmp-it.land{animation:v2-atxcmpland .64s cubic-bezier(.3,.7,.4,1) calc(160ms + var(--i,0) * 90ms) backwards}
@keyframes v2-atxcmpland{0%{opacity:0;transform:translateY(-28px) rotate(var(--r,0deg)) scale(.92)}45%{opacity:1;transform:translateY(2px) rotate(0deg) scale(1.02,.98)}70%{transform:translateY(-1.5px) scale(1)}100%{transform:none}}
.v2 .atx-cmp-th{position:relative;height:72px;border-radius:var(--r-in);overflow:hidden;background:var(--wash);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--rail) 50%,transparent);transition:box-shadow .3s,transform .3s var(--ease)}
.v2 .atx-cmp-th .atx-art{padding:var(--s-2) var(--s-3) 0}
.v2 .atx-cmp-veil{position:absolute;inset:0;background:color-mix(in srgb,var(--surface) 72%,transparent);clip-path:inset(0 0 calc(var(--p,0) * 100%) 0);transition:clip-path .2s linear}
.v2 .atx-cmp-it.up .atx-cmp-veil{opacity:0;transition:opacity .4s}
.v2 .atx-cmp-scan{position:absolute;left:0;right:0;top:0;height:40%;z-index:1;background:linear-gradient(180deg,transparent,color-mix(in srgb,var(--fg) 7%,transparent),transparent);transform:translateY(-100%);opacity:0;pointer-events:none}
.v2 .atx-cmp-it.read .atx-cmp-scan{opacity:1;animation:v2-atxcmpscan 1.2s var(--ease-io) infinite}
@keyframes v2-atxcmpscan{from{transform:translateY(-100%)}to{transform:translateY(250%)}}
.v2 .atx-cmp-pc{position:absolute;left:6px;bottom:5px;z-index:2;font-size:11px;font-weight:500;color:var(--fg)}
.v2 .atx-cmp-it.up .atx-cmp-pc{display:none}
.v2 .atx-cmp-bd{position:absolute;left:6px;top:6px;z-index:2}
/* on the grey picture the kind tag is white, so it is never grey on grey */
.v2 .atx-cmp-bd .tag{background:var(--surface)}
.v2 .atx-cmp-ok{position:absolute;right:5px;bottom:5px;z-index:2;width:16px;height:16px;border-radius:50%;display:grid;place-items:center;background:var(--ok);color:#fff;transform:scale(0);transition:transform .4s var(--ease)}
.v2 .atx-cmp-ok .i{width:10px;height:10px;stroke-width:2.4;color:inherit}
:root[data-theme="dark"] .v2 .atx-cmp-ok{color:#0b2414}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .v2 .atx-cmp-ok{color:#0b2414}}
.v2 .atx-cmp-it.done .atx-cmp-ok{transform:none}
.v2 .atx-cmp-x{position:absolute;right:-6px;top:-6px;z-index:4;width:20px;height:20px;border-radius:50%;display:grid;place-items:center;background:var(--raised);color:var(--fg);box-shadow:var(--shadow-pop);opacity:0;transform:scale(.7);transition:opacity .2s,transform .25s var(--ease)}
.v2 .atx-cmp-x .i{width:10px;height:10px;stroke-width:2.2;color:inherit}
.v2 .atx-cmp-it:focus-within .atx-cmp-x,.v2 .atx-cmp-it.peek .atx-cmp-x{opacity:1;transform:none}
@media (hover:hover) and (pointer:fine){.v2 .atx-cmp-it:hover .atx-cmp-x{opacity:1;transform:none}}
@media (hover:none){.v2 .atx-cmp-x{opacity:1;transform:none}}
.v2 .atx-cmp-n{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--fg)}
.v2 .atx-cmp-m{margin-top:-4px;font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .atx-cmp-m .shim{font-size:inherit}
.v2 .atx-cmp-it.gone{animation:v2-atxcmpgone .3s var(--ease) forwards}
@keyframes v2-atxcmpgone{to{opacity:0;transform:scale(.85)}}
/* the message is a field of its own (the site's field look: a dimmed edge at rest, one step stronger with the focus), so it
   reads as the place to type, in both styles and themes */
.v2 .atx-cmp-ta{display:block;width:100%;resize:none;border:0;outline:0;background:var(--surface);padding:10px var(--s-3);border-radius:var(--r-box);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line) 50%,transparent);font:inherit;font-size:13.5px;line-height:1.5;color:var(--fg)}
@supports (corner-shape:squircle){.v2 .atx-cmp-ta{corner-shape:squircle;border-radius:var(--r-box-sq)}}
.v2 .atx-cmp-ta:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line-strong) 50%,transparent)}
.v2 .atx-cmp-ta::placeholder{color:var(--muted)}
/* the field lines up with the files above it (the tray's own inset), and so do + and send below it */
.v2 .atx-cmp-ta{width:auto;margin-inline:var(--s-2);max-height:72px;margin-top:var(--s-1);transition:max-height .35s var(--ease),opacity .25s,padding .35s var(--ease),margin .35s var(--ease),box-shadow .2s}
.v2 .atx-cmp-box.none .atx-cmp-ta{max-height:0;padding-block:0;margin-top:0;opacity:0;visibility:hidden}
/* + and send sit with the field's edges, with the same room above them (the box's gap and this) as below (this and the box's padding) */
.v2 .atx-cmp-f{display:flex;align-items:center;gap:var(--s-2);padding:var(--s-2)}
.v2 .atx-cmp-add{position:relative;overflow:hidden;cursor:pointer}
.v2 .atx-cmp-add:has(.atx-pick:focus-visible){outline:2px solid var(--focus);outline-offset:2px}
.v2 .atx-cmp-st{flex:1;font-size:12px;color:var(--muted)}
.v2 .atx-cmp-send{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--accent);color:var(--on-accent,#fff);transition:background .2s,transform .15s}
.v2 .atx-cmp-send .i{color:inherit}
@media (hover:hover) and (pointer:fine){.v2 .atx-cmp-send:hover{background:var(--accent-2)}}
.v2 .atx-cmp-send:active{transform:scale(.92)}
.v2 .atx-cmp-send[disabled]{cursor:not-allowed;background:var(--dis-hatch),var(--dis-fill);color:var(--dis);box-shadow:var(--soft-ring)}
/* a file dragged over the box: the box veils over, says so, and its edge is a quiet grey at half strength */
.v2 .atx-cmp-over{position:absolute;inset:0;z-index:5;display:grid;place-items:center;border-radius:inherit;background:color-mix(in srgb,var(--surface) 92%,transparent);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--faint) 50%,transparent);opacity:0;pointer-events:none;transition:opacity .25s}
.v2 .atx-cmp-over span{display:inline-flex;align-items:center;gap:var(--s-2);font-size:13px;font-weight:500;color:var(--fg)}
.v2 .atx-cmp-over .i{animation:v2-atxbob .9s var(--ease-io) infinite}
.v2 .atx-cmp-box.over .atx-cmp-over{opacity:1}
@container (max-width:380px){.v2 .atx-cmp-art{width:96px;height:64px}.v2 .atx-cmp-empty{gap:var(--s-2);padding:0 var(--s-2)}}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .atx-cmp-veil{background:repeating-linear-gradient(135deg,transparent 0 4px,color-mix(in srgb,var(--fg) 10%,transparent) 4px 5px),color-mix(in srgb,var(--surface) 70%,transparent)}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .atx-cmp-it.read .atx-cmp-scan{height:2px;background:var(--muted);animation:v2-atxcmpscanbp 1.2s steps(6,end) infinite}
@keyframes v2-atxcmpscanbp{from{transform:translateY(0)}to{transform:translateY(72px)}}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .atx-cmp-over{background:repeating-linear-gradient(135deg,transparent 0 6px,color-mix(in srgb,var(--fg) 8%,transparent) 6px 7px),color-mix(in srgb,var(--surface) 92%,transparent)}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .atx-cmp-over .i{animation:v2-bpblink 1s steps(1,end) infinite}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .atx-cmp-ok{transition:transform .2s steps(2,end)}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .atx-cmp-it.land{animation:v2-atxcmplandbp .36s steps(4,end) calc(160ms + var(--i,0) * 90ms) backwards}
@keyframes v2-atxcmplandbp{0%{opacity:0;transform:translateY(-12px)}50%{opacity:1}100%{transform:none}}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .atx-cmp-box.thud{animation:none}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .atx-cmp-art .sh{animation:none}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .atx-cmp-empty.out .sh{transition:transform .2s steps(2,end),opacity .2s steps(2,end)}
/* Clean: the box takes the card's 22px corners and grows with what it holds (grow()). Its bottom row is not a strip, so +
   and Send sit on the content's 16px edges, + under the field's left edge and Send under its right (owner, 18 Nov; both
   28px). Send is the ink button. The layer that says "Drop to attach" takes the card's corners (inside grow()'s wrapper it
   would inherit none). The empty tray is Clean's empty state (.atx-em,
   in Attachment tray), 16px in from the box's top, in the box's own flow so the box is as tall as it; as the first files land
   it lies over the tray while it fades, so the box goes straight to the files' height. The previews are rounded pictures, not
   circles, and a preview's remove button sits inside its corner, so nothing reaches past the box's 16px */
:root[data-style="clean"] .v2 .atx-cmp-box{border-radius:var(--r-card);transition:height .55s cubic-bezier(.22,1,.36,1),box-shadow .3s}
:root[data-style="clean"] .v2 :is(.atx-cmp-tray,.atx-cmp-list){min-height:0}
:root[data-style="clean"] .v2 .atx-cmp-list:empty{padding:0}
/* the tray scrolls sideways when its files outrun it (on a phone, or with more files); its edges sit on the content's 16px
   line, so a file passing under them is cut there, and a file's focus ring is drawn just inside it */
:root[data-style="clean"] .v2 .atx-cmp-list:not(:empty){margin-inline:8px;padding-inline:0}
:root[data-style="clean"] .v2 .atx-cmp-it:focus-visible{outline-offset:-2px}
:root[data-style="clean"] .v2 .atx-cmp-empty{position:relative;inset:auto;justify-content:flex-start;gap:4px;padding:8px 8px 0;border:0;border-radius:0;background:none;box-shadow:none;pointer-events:auto}
:root[data-style="clean"] .v2 .atx-cmp-empty.out{position:absolute;inset:0 0 auto;pointer-events:none}
:root[data-style="clean"] .v2 .atx-cmp-x{right:4px;top:4px}
:root[data-style="clean"] .v2 .atx-cmp-it,:root[data-style="clean"] .v2 .atx-cmp-th,:root[data-style="clean"] .v2 .atx-cmp-it:focus-visible{border-radius:12px}
:root[data-style="clean"] .v2 .atx-cmp-f{padding:8px}
:root[data-style="clean"] .v2 .atx-cmp-over{border-radius:var(--r-card)}
:root[data-style="clean"] .v2 .atx-cmp-add{width:28px;height:28px}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] .v2 .atx-cmp-box{transition:none}}
:root[data-style="clean"] .v2 .atx-cmp-send{width:28px;height:28px;border-radius:calc(var(--r-card) - 16px)}
/* (the green a step towards --ok, as Classic's foot-strip tick, so the badge keeps 3:1 on the picture's off-white) */
:root[data-style="clean"] .v2 .atx-cmp-ok{background:color-mix(in srgb,var(--ok-mark) 80%,var(--ok));color:var(--surface)}

/* Context budget: what each file costs the agent's context. The window bar has the instructions first in grey, then each
   file in a step of the accent, as wide as its share; the same step marks the file's row. Each part is drawn across the
   whole bar and clipped to its stretch (--a to --b, in percent), so as a share grows the parts slide with a clip and the
   bar is never laid out again. A file too big to read whole is hatched, and says how much of it the agent keeps */
.v2 .atx-ctx{padding:var(--s-4);display:flex;flex-direction:column;gap:var(--s-3)}
.v2 .atx-ctx-h{display:flex;align-items:center;justify-content:space-between;gap:var(--s-3)}
.v2 .atx-ctx-ht{display:flex;flex-direction:column}
.v2 .atx-ctx-ht b{font-weight:500}
.v2 .atx-ctx-st{font-size:12.5px;color:var(--muted)}
.v2 .atx-ctx-pc{font-size:13px;font-weight:500;color:var(--fg2)}
.v2 .atx-ctx-bar{position:relative;height:12px;border-radius:var(--r-tag);background:color-mix(in srgb,var(--line) 55%,transparent);overflow:hidden}
.v2 .atx-ctx-bar i{position:absolute;inset:2px;display:block;border-radius:2px;clip-path:inset(0 calc(100% - var(--b,0) * 1% + 1px) 0 calc(var(--a,0) * 1% + 1px) round 2px);transition:clip-path .6s var(--ease),opacity .3s}
.v2 .atx-ctx-bar .sys{background:var(--muted)}
.v2 .atx-ctx-segs{display:contents}
.v2 .atx-ctx-segs i{background:var(--c)}
/* a share still being counted breathes, and one cut short is hatched */
.v2 .atx-ctx-segs i.live{animation:v2-atxctxlive 1.2s var(--ease-io) infinite}
@keyframes v2-atxctxlive{50%{opacity:.55}}
.v2 .atx-ctx-segs i.cut{background:repeating-linear-gradient(135deg,var(--c) 0 3px,color-mix(in srgb,var(--c) 45%,var(--surface)) 3px 6px)}
.v2 .atx-ctx-key{display:flex;justify-content:space-between;gap:var(--s-2);font-size:11.5px;color:var(--muted);margin-top:-4px}
.v2 .atx-ctx-key span{display:inline-flex;align-items:center;gap:var(--s-1)}
/* the legend's swatch is the instructions' part in small: the same grey and corners, its left edge on that part's (the bar's 2px
   inset and the part's 1px gap) */
.v2 .atx-ctx-key i{width:8px;height:8px;margin-left:3px;border-radius:2px;background:var(--muted)}
.v2 .atx-ctx-list{list-style:none;margin:0 calc(-1 * var(--s-2));padding:0;display:flex;flex-direction:column}
.v2 .atx-ctx-it{border-radius:var(--r-in);transition:background .25s,opacity .3s}
@media (hover:hover) and (pointer:fine){.v2 .atx-ctx-it:hover{background:var(--row)}}
.v2 .atx-ctx-r{display:flex;align-items:center;gap:var(--s-3);min-height:48px;padding:var(--s-2)}
.v2 .atx-ctx-ic{position:relative;width:30px;height:30px;flex:none;border-radius:calc(8px * var(--rk-m,var(--rk)));display:grid;place-items:center;background:var(--chip);color:var(--fg2)}
@media (hover:hover) and (pointer:fine){.v2 .atx-ctx-it:hover .atx-ctx-ic{background:var(--surface)}}
/* uploading: a short line in the accent along the foot of the tile, growing with a transform */
.v2 .atx-ctx-up{position:absolute;left:var(--s-1);right:var(--s-1);bottom:3px;height:2px;border-radius:var(--r-xs);background:var(--accent-mark);transform-origin:left;transform:scaleX(var(--p,0));transition:transform .2s linear}
.v2 .atx-ctx-it.up .atx-ctx-up{opacity:0;transition:opacity .4s}
