.v2 .itd-f:empty{display:none}
/* Clean: the line saying how the review went is the card's off-white foot strip (owner, 21 Nov), its words 16px in */
:root[data-style="clean"] .v2 .itd-f{padding-top:0;border-top:0}
:root[data-style="clean"] .v2 .itd.panel .itd-f{margin:var(--s-1) -16px -16px;padding:13px 16px;background:var(--strip);border-top:1px solid var(--line);border-radius:0 0 var(--r-card) var(--r-card);line-height:18px}
