:root[data-style="clean"] .v2 .itd.panel{padding:16px}
:root[data-style="clean"] .v2 .itd-ht b{line-height:20px}
:root[data-style="clean"] .v2 .itd-st{line-height:18px}
:root[data-style="clean"] .v2 .itd-c{transition:background-color var(--t-fast) var(--ease)}
:root[data-style="clean"] .v2 .itd-bar{border-radius:var(--r-card);transform:translateY(-4px) scale(.96);transform-origin:top left;transition:opacity var(--t-fast) var(--ease),transform var(--t) var(--ease),visibility 0s var(--t)}
:root[data-style="clean"] .v2 .itd-bar.up{transform:translateY(4px) scale(.96);transform-origin:bottom left}
:root[data-style="clean"] .v2 .itd-bar.open{transform:none;transition-delay:0s}
:root[data-style="clean"] .v2 .itd-bar.unsure .itd-acc{color:var(--fg);background:linear-gradient(180deg,var(--btn2-1),var(--btn2-2));box-shadow:var(--btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .itd-bar.unsure .itd-acc:hover{color:var(--fg);background:linear-gradient(180deg,var(--btn2-1),var(--btn2-2));box-shadow:var(--btn2-depth)}}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .itd-bar.unsure .itd-acc:hover{box-shadow:var(--btn2-hover)}}
