.v2 .ahx-ws{display:flex;align-items:center;gap:2px;margin-bottom:6px}
.v2 .ahx-wsb{flex:1;min-width:0;display:flex;align-items:center;gap:9px;height:34px;padding:0 var(--s-2) 0 7px;border-radius:calc(10px * var(--rk-m,var(--rk)));font-size:13.5px;font-weight:500;color:var(--fg);transition:background var(--t-fast)}
