.v2 .dnx-svg .tr{fill:var(--dnx-track);stroke:var(--dnx-track);cursor:auto}
.v2 .dnx-g.hov path:not(.hl,.tr){opacity:.3}
.v2 .dnx-c{position:absolute;left:0;right:0;bottom:0;display:flex;flex-direction:column;align-items:center;pointer-events:none}
.v2 .dnx-c b{font-size:14px;line-height:20px;font-weight:500;letter-spacing:-.01em;color:var(--fg)}
.v2 .dnx-c span{font-size:12px;line-height:16px}
/* the last row's words end 16px from the card's foot, its hover fill reaching out round them */
.v2 .dnx-lg{position:relative;display:flex;flex-direction:column;gap:2px;margin:0 calc(-1 * var(--s-2)) calc(-1 * var(--s-2))}
.v2 .dnx-r{position:relative;display:flex;align-items:center;gap:var(--s-2);width:100%;padding:6px var(--s-2);border-radius:calc(9px * var(--rk-m,var(--rk)));font-size:13px;line-height:20px;text-align:left;transition:background-color var(--t-fast) var(--ease)}
.v2 .dnx-r.hl{background:var(--row)}
@media (hover:hover) and (pointer:fine){.v2 .dnx-r:hover{background:var(--row)}}
.v2 .dnx-r.sel{background:color-mix(in srgb,var(--fg) 9%,transparent)}
.v2 .dnx-r.sel .t{color:var(--fg)}
.v2 .dnx-svg path[data-i]{cursor:pointer}
/* the hover that glides from row to row is Clean's (below); the other styles fill the row itself */
.v2 .dnx-hv{display:none}
.v2 .dnx-r:focus-visible{outline-offset:-2px}
.v2 .dnx-r i{width:3px;height:14px;border-radius:2px;flex:none}
.v2 .dnx-r .t{flex:1;min-width:0;color:var(--fg2)}
.v2 .dnx-r .v{color:var(--fg)}
/* Blueprint: square corners on the parts and the track */
:root:not([data-style="soft"],[data-style="clean"]) .v2 .dnx-svg path{stroke-linejoin:miter}
/* Clean (owner, 21 Nov: "it definitely has to be updated"): the title on an off-white head strip that follows the card's
   corners; a slimmer ring (14px against Soft's 18) with a little rounder corners (5px against 4); the track recessed with
   Clean's inner shadow (an SVG filter, since a path takes no inset box-shadow); the legend
   Clean's 10px rows with its one hover, a neutral fill that eases in over 220ms and glides from row to
   row (it only fades with reduced motion), and the selected row a stronger fill of the same shape. The middle's figure is set
   with tabular figures and Clean's tighter tracking. In Clean dark the accent is white (owner, 21 Nov; Clean dark's tokens),
   so the first part is white; the other parts keep the palette's hues */
:root[data-style="clean"] .v2 .dnx{--dnx-th:14;--dnx-cr:5}
:root[data-style="clean"] .v2 .dnx-h{margin:calc(-1 * var(--s-4)) calc(-1 * var(--s-4)) 0;padding:12px var(--s-4);background:var(--strip);border-bottom:1px solid var(--line);border-radius:var(--r-card) var(--r-card) 0 0;font-size:13px;line-height:20px;font-weight:500}
:root[data-style="clean"] .v2 .dnx-svg .tr{filter:var(--dnx-in)}
:root[data-style="clean"] .v2 .dnx-svg .dnx-in-s{flood-color:rgba(0,0,0,.12)}
:root[data-style="clean"] .v2 .dnx-svg .dnx-in-r{flood-color:rgba(0,0,0,.04)}
:root[data-style="clean"] .v2 .dnx-c b{letter-spacing:-.02em;font-variant-numeric:tabular-nums}
:root[data-style="clean"] .v2 .dnx-c span{color:var(--muted);letter-spacing:0}
:root[data-style="clean"] .v2 .dnx-r{border-radius:var(--r-in)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .dnx-lg.gl .dnx-r:is(:hover,.hl){background:transparent}}
:root[data-style="clean"] .v2 .dnx-r.sel,:root[data-style="clean"] .v2 .dnx-lg.gl .dnx-r.sel{background:color-mix(in srgb,var(--fg) 11%,var(--surface))}
:root[data-style="clean"] .v2 .dnx-hv{display:block;position:absolute;left:0;right:0;top:0;height:32px;border-radius:var(--r-in);background:var(--hover);opacity:0;pointer-events:none;transition:opacity var(--t-fast) var(--ease),transform var(--t-fast) var(--ease),height var(--t-fast) var(--ease)}
:root[data-style="clean"][data-theme="dark"] .v2 .dnx-svg .dnx-in-s{flood-color:rgba(0,0,0,.5)}
:root[data-style="clean"][data-theme="dark"] .v2 .dnx-svg .dnx-in-r{flood-color:rgba(255,255,255,.05)}
@media (prefers-color-scheme:dark){
  :root[data-style="clean"]:not([data-theme="light"]) .v2 .dnx-svg .dnx-in-s{flood-color:rgba(0,0,0,.5)}
  :root[data-style="clean"]:not([data-theme="light"]) .v2 .dnx-svg .dnx-in-r{flood-color:rgba(255,255,255,.05)}}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] .v2 .dnx-hv{transition:opacity var(--t-fast) var(--ease)}}
/* ---------- Funnel ---------- */
.v2 .fnx{padding:var(--s-4);display:flex;flex-direction:column;gap:var(--s-3)}
.v2 .fnx-h{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:13.5px;flex-wrap:wrap}
.v2 .fnx-h b{font-weight:500}
.v2 .fnx-sg button{font-size:12px;height:26px;padding:0 9px}
.v2 .fnx-rows{display:flex;flex-direction:column;gap:6px}
.v2 .fnx-r{display:grid;grid-template-columns:118px 1fr 48px;align-items:center;gap:10px;font-size:12.5px;padding:2px 0;border-radius:var(--r-sm)}
.v2 .fnx-r .k{color:var(--fg2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .fnx-r .tr{height:26px;border-radius:var(--r-sm);background:var(--chip);position:relative;overflow:hidden}
/* the bar is an accent fill, so its count reads in --on-accent; its edge in the mark keeps a light accent visible on the track */
.v2 .fnx-r .bar{position:absolute;inset:0 auto 0 0;border-radius:var(--r-sm);background:var(--accent);box-shadow:inset 0 0 0 1px var(--accent-mark,var(--accent));transition:width .9s var(--ease),opacity .3s}
.v2 .fnx-r .n{position:absolute;left:10px;top:0;bottom:0;display:flex;align-items:center;color:var(--on-accent,#fff);font-size:11.5px;font-weight:500;transition:left .9s var(--ease),color .3s}
.v2 .fnx-r .n.out{color:var(--fg2)}
.v2 .fnx-r .bar{background:var(--fc,var(--accent));box-shadow:none}
/* a funnel bar is lime with no outline: its count is written on it, so the bar never carries the value alone (owner, 10 Nov) */
:root:not([data-style="soft"],[data-style="clean"]) .v2 .fnx-r .bar{background:var(--accent);box-shadow:none}
.v2 .fnx-r .v{text-align:right;color:var(--muted);font-size:12px}
.v2 .fnx-r.drop .v{color:var(--bad);font-weight:500}
@media (hover:hover) and (pointer:fine){.v2 .fnx-rows:hover .fnx-r:not(:hover) .bar{opacity:.35}}
.v2 .fnx-ins{display:flex;gap:var(--s-2);font-size:12.5px;line-height:1.5;color:var(--fg2);padding:10px var(--s-3);border-radius:var(--r-in);background:var(--accent-bg)}
.v2 .fnx-ic{color:var(--accent-fg,var(--accent));display:grid;margin-top:2px}
/* Clean: equal padding (owner, 17 Nov; 16px since 18 Nov): its content 16px in from every edge, the insight too (owner, 21 Nov:
   it sat 7px from the bottom) */
:root[data-style="clean"] .v2 .fnx.panel{padding:16px}
/* ---------- Top pages ---------- */
.v2 .tpx{padding:var(--s-4);display:flex;flex-direction:column;gap:10px}
.v2 .tpx-h{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;padding:0 2px}
.v2 .tpx-h>div:first-child{display:flex;flex-direction:column;font-size:13.5px}
.v2 .tpx-h b{font-weight:500}
.v2 .tpx-sub{font-size:12px}
.v2 .tpx-sg button{font-size:12px;height:26px;padding:0 9px}
.v2 .tpx-list{position:relative;height:calc(6 * 50px)}
.v2 .tpx-r{position:absolute;left:0;right:0;height:46px;display:grid;grid-template-columns:20px 1fr 56px 60px;align-items:start;gap:10px;padding:9px var(--s-2) 0;border-radius:var(--r-in);transition:transform .55s var(--ease),background .2s}
@media (hover:hover) and (pointer:fine){.v2 .tpx-r:hover{background:var(--row)}}
.v2 .tpx-r .rk{font-family:var(--mono);font-size:11px;line-height:19.5px;color:var(--muted);text-align:center;transition:color .2s}
@media (hover:hover) and (pointer:fine){.v2 .tpx-r:hover .rk{color:var(--fg)}}
.v2 .tpx-r .pg{display:flex;flex-direction:column;gap:5px;min-width:0}
.v2 .tpx-r .p{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .tpx-r .tr{height:4px;border-radius:var(--r-tiny,2px);background:var(--chip);overflow:hidden}
@media (hover:hover) and (pointer:fine){.v2 .tpx-r:hover .tr{background:var(--surface)}}
.v2 .tpx-r .tr i{display:block;height:100%;width:0;border-radius:var(--r-tiny,2px);background:var(--accent-mark,var(--accent));transition:width .9s var(--ease)}
.v2 .tpx-r .n{font-size:13px;font-weight:500;min-width:52px;text-align:right}
.v2 .tpx-r .ch{justify-self:end;padding:0 6px}
/* Clean: equal padding (owner, 17 Nov): its content 20px in from every edge */
:root[data-style="clean"] .v2 .tpx.panel{padding:18px 16px 0px 18px}
/* ---------- Health score ---------- */
/* an account's health: the score in a small ring with its verdict, the four factors as rows under one another (each with its
   status dot and its figure, opening its detail right under it) and the agent's next move with its button. The rows are split
   by hairlines, with no fill, shadow or card of their own (owner, 9 Nov). The state shows only in the status dots and the
   ring, and the weakest factor off track gets an ink label */
.v2 .hsc{display:flex;flex-direction:column;gap:var(--s-3);width:100%;padding:var(--s-4);container-type:inline-size;--vm:var(--ok-mark);--vf:var(--ok)}
.v2 .hsc[data-v="warn"]{--vm:var(--warn-mark);--vf:var(--warn)}
.v2 .hsc[data-v="bad"]{--vm:var(--bad-mark);--vf:var(--bad)}
.v2 .hsc-sr{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
/* the account it is about, when the block stands on its own (a details sheet that names the account leaves it out) */
.v2 .hsc-ac{display:flex;flex-direction:column;align-items:flex-start;padding-bottom:var(--s-3);border-bottom:1px solid color-mix(in srgb,var(--line) 50%,transparent);line-height:1.4}
.v2 .hsc-ac b{font-size:14px;font-weight:500}
.v2 .hsc-ac>span{font-size:12.5px;color:var(--muted)}
/* the header line: the score in its ring, the verdict and how it moved */
.v2 .hsc-h{display:flex;align-items:center;gap:var(--s-3)}
.v2 .hsc-ring{position:relative;flex:none;width:44px;height:44px;display:grid;place-items:center}
.v2 .hsc-ring svg{position:absolute;inset:0;width:100%;height:100%;transform:rotate(-90deg);overflow:visible}
.v2 .hsc-ring circle{fill:none;stroke-width:4}
.v2 .hsc-ring .tr{stroke:var(--line)}
.v2 .hsc-ring .fl{stroke:var(--vm);stroke-linecap:round;transition:stroke-dashoffset .9s var(--ease),stroke var(--t) var(--ease)}
.v2 .hsc-ring b{position:relative;font-size:14px;font-weight:500;letter-spacing:-.01em;line-height:1}
.v2 .hsc-ht{flex:1;min-width:0;display:flex;flex-direction:column;align-items:flex-start;line-height:1.4}
.v2 .hsc-vd{font-size:14px;font-weight:500;color:var(--vf);transition:color var(--t) var(--ease)}
.v2 .hsc-sub{font-size:12.5px;color:var(--muted);text-wrap:pretty}
.v2 .hsc-dl{flex:none;align-self:flex-start;margin-top:4px;font-size:12.5px;color:var(--muted)}
/* the factors: a row each, a hairline above every row. A row is its status dot and name (and Weakest), its figure and unit,
   and a chevron; its detail opens right under it */
.v2 .hsc-l{display:flex;flex-direction:column}
.v2 .hsc-t{display:grid;grid-template-columns:minmax(0,1fr) auto 16px;grid-template-areas:"k v cv";align-items:center;column-gap:var(--s-3);width:100%;min-height:44px;padding:10px 0;border-top:1px solid color-mix(in srgb,var(--line) 50%,transparent);text-align:left;--sm:var(--ok-mark)}
.v2 .hsc-t[data-s="warn"]{--sm:var(--warn-mark)}
.v2 .hsc-t[data-s="bad"]{--sm:var(--bad-mark)}
.v2 .hsc-t:focus-visible{outline-offset:-2px;border-radius:var(--r-sm)}
.v2 .hsc-k{grid-area:k;display:flex;align-items:center;gap:6px;min-width:0;font-size:13px;line-height:20px;color:var(--fg2);transition:color var(--t-fast)}
.v2 .hsc-n{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .hsc-dot{flex:none;width:8px;height:8px;border-radius:50%;background:var(--sm);transition:background var(--t) var(--ease)}
/* under the score's head the rows share its columns (owner, 18 Nov): the status dot centred under the ring's 44px column, the
   name and an open row's detail where the verdict's words start. (Rows on their own, as in a sheet that shows only the
   factors, keep the dot before the name) */
.v2 .hsc-h~.hsc-l .hsc-k{position:relative;padding-left:56px}
.v2 .hsc-h~.hsc-l .hsc-dot{position:absolute;left:18px;top:6px}
.v2 .hsc-h~.hsc-l .hsc-dc{padding-left:56px}
/* the weakest factor that is off track says so in ink, never with a fill */
.v2 .hsc-wk{flex:none;display:none;margin-left:2px;font-size:11px;font-weight:500;line-height:16px;color:var(--fg)}
.v2 .hsc-t[data-weak] .hsc-wk{display:block}
.v2 .hsc-v{grid-area:v;display:flex;align-items:baseline;justify-content:flex-end;gap:5px;white-space:nowrap;line-height:20px}
.v2 .hsc-v b{font-size:14px;font-weight:500;letter-spacing:-.01em;color:var(--fg)}
.v2 .hsc-v>span{font-size:12px;color:var(--muted)}
.v2 .hsc-cv{grid-area:cv;justify-self:end;color:var(--muted);transition:transform var(--t) var(--ease),color var(--t-fast)}
.v2 .hsc-t[aria-expanded="true"] .hsc-k{color:var(--fg)}
.v2 .hsc-t[aria-expanded="true"] .hsc-cv{transform:rotate(180deg);color:var(--fg2)}
@media (hover:hover) and (pointer:fine){
  .v2 .hsc-t:hover .hsc-k{color:var(--fg)}
  .v2 .hsc-t:hover .hsc-cv{color:var(--fg2)}
}
/* a row's detail: plain lines under its name, no card */
.v2 .hsc-dc{padding:0 0 var(--s-3) 14px}
.v2 .hsc-dp{margin:0;font-size:12.5px;line-height:1.5;color:var(--fg);text-wrap:pretty}
.v2 .hsc-dp+.hsc-dp{margin-top:2px;color:var(--fg2)}
.v2 .hsc-pt{display:flex;align-items:center;gap:var(--s-2);margin:var(--s-2) 0 0;font-size:12px;color:var(--muted)}
.v2 .hsc-pt i{width:4px;height:4px;border-radius:50%;background:var(--faint)}
/* the agent's next move: a plain row under a hairline, the spark centred in the ring's column on the first line of its words,
   the words on the verdict's column, and its button on the content's right edge, centred on the words */
.v2 .hsc-s{display:flex;align-items:center;gap:var(--s-3);min-height:44px;padding-top:var(--s-3);border-top:1px solid color-mix(in srgb,var(--line) 50%,transparent);font-size:12.5px;line-height:1.45;color:var(--fg2)}
.v2 .hsc-say{flex:1;min-width:0;display:flex;align-items:flex-start}
.v2 .hsc-say .i{flex:none;margin:2px 27px 0 15px;color:var(--accent-mark,var(--accent))}
/* its words ease to a new line count rather than jump (grow()), the spark and words staying side by side */
.v2 .hsc-say>.dm-grow{flex:1 1 auto;min-width:0;flex-direction:row;align-items:flex-start}
.v2 .hsc-st{flex:1;min-width:0;text-wrap:pretty}
.v2 .hsc-s .pill{flex:none}
.v2 .hsc-s .pill .spin{width:12px;height:12px}
.v2 .hsc-done{flex:none;outline:0}
.v2 .hsc-done .i{margin-left:-1px}
/* Blueprint: square marks, labels in small capitals */
:root:not([data-style="soft"],[data-style="clean"]) .v2 :is(.hsc-k,.hsc-pt){font-size:11px;font-weight:500;letter-spacing:.04em;text-transform:uppercase}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .hsc-done{font-size:11px}
/* Clean (owner, 18 Nov): the content 16px in from every edge; a factor row's hover is a quiet fill as wide as the content (the
   ring's box) with rounded corners, in place of the hairlines round it, and the chevron sits 8px inside it. The spark is the
   quiet grey of Clean's chrome */
:root[data-style="clean"] .v2 .hsc-h~.hsc-l .hsc-t{padding-right:var(--s-2);transition:background-color var(--t-fast) var(--ease),border-color var(--t-fast) var(--ease)}
:root[data-style="clean"] .v2 .hsc-say .i{color:var(--fg2)}
/* Clean (owner, 21 Nov: "clean up the bottom part… make it look more like the Clean component… try not to break the text into
   three lines… if you have to, make the text span full width and add a button below that… Clean is just Soft with a different
   corner radius"). The account sits in an off-white head strip and the agent's next move in an off-white foot strip, each
   under a hairline, edge to edge. In the foot its words run the strip's width (two lines at most) on the verdict's column, the
   spark in the ring's, and its button (or Booked) sits under them on the same column. The factors are Clean's 10px rows with no
   hairlines between them, under one gliding hover (hoverGlide); the ring's track is sunk with Clean's inner shadow */
:root[data-style="clean"] .v2 .hsc.panel{padding:0 16px}
:root[data-style="clean"] .v2 .hsc-ac{margin:0 -16px;padding:12px 16px;background:var(--strip);border-bottom:1px solid var(--line);border-radius:var(--r-card) var(--r-card) 0 0}
:root[data-style="clean"] .v2 .hsc-h{margin-top:4px}
:root[data-style="clean"] .v2 .hsc-ring .tr{stroke:transparent}
:root[data-style="clean"] .v2 .hsc-ring::before{content:"";position:absolute;inset:calc(100% * 2 / 44);border-radius:50%;background:var(--soft);box-shadow:var(--track-ring);-webkit-mask:radial-gradient(circle closest-side,transparent calc(80% - .5px),#000 80%);mask:radial-gradient(circle closest-side,transparent calc(80% - .5px),#000 80%)}
:root[data-style="clean"] .v2 .hsc-h~.hsc-l{gap:2px}
:root[data-style="clean"] .v2 .hsc-h~.hsc-l .hsc-t{border-top:0;border-radius:10px;padding-right:var(--s-2)}
:root[data-style="clean"] .v2 .hsc-s{flex-direction:column;align-items:flex-start;gap:8px;margin:4px -16px 0;padding:12px 16px;background:var(--strip);border-top:1px solid var(--line);border-radius:0 0 var(--r-card) var(--r-card)}
:root[data-style="clean"] .v2 .hsc-say{align-self:stretch;flex:none}
/* (on a narrow block the foot keeps its one column: the words, then the button under them, never a second column) */
:root[data-style="clean"] .v2 .hsc-s{flex-wrap:nowrap}
:root[data-style="clean"] .v2 .hsc-s :is(.pill,.hsc-done){margin-left:56px}
/* a narrow block (a phone, a slim sheet): the button goes under the agent's line */
@container (max-width:359px){
  .v2 .hsc-h~.hsc-l .hsc-k{flex-direction:column;align-items:flex-start;gap:0}
  .v2 .hsc-h~.hsc-l .hsc-wk{margin-left:0}
  .v2 .hsc-s{flex-wrap:wrap;row-gap:var(--s-2)}
  .v2 .hsc-say{flex:1 1 100%}
  .v2 .hsc-s :is(.pill,.hsc-done){margin-left:56px}
}
/* ---------- Activity heatmap ---------- */
.v2 .hmx{padding:var(--s-4);display:flex;flex-direction:column;gap:10px}
/* the ramp (owner, 20 Nov: "saturate the greens and blues"): from a light tint of the chart's mark colour to that colour at
   full strength, mixed in oklch so the steps between stay vivid rather than greying. The busiest cells, and the key's More,
   are the mark colour a touch toward the text, so they keep 3:1 on the card with room to spare (the blue in Soft and Clean,
   Blueprint's green in light and its lime in dark), and the key shows the same ramp as the cells. In dark mode the quiet end
   is a deeper tint, so it still reads against the card */
.v2 .hmx{--hm-hi:color-mix(in oklch,var(--accent-mark,var(--accent)) 92%,var(--fg));--hm-lo:color-mix(in oklch,var(--hm-hi) 13%,var(--surface))}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .v2 .hmx{--hm-lo:color-mix(in oklch,var(--hm-hi) 22%,var(--surface))}}
:root[data-theme="dark"] .v2 .hmx{--hm-lo:color-mix(in oklch,var(--hm-hi) 22%,var(--surface))}
/* the head sits over a hairline in every style (owner, 21 Nov), 10px from it on each side as the card's other gaps */
.v2 .hmx-h{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-bottom:10px;border-bottom:1px solid color-mix(in srgb,var(--line) 50%,transparent)}
.v2 .hmx-h>div:first-child{display:flex;flex-direction:column;font-size:13.5px;line-height:1.4}
.v2 .hmx-h b{font-weight:500}
.v2 .hmx-st{font-size:12px}
.v2 .hmx-sg button{font-size:12px;height:26px;padding:0 9px}
/* the day names, the cells and the hour names sit in one grid, so the hour names line up with the cells; on a phone the
   grid scrolls sideways (below) and the day names stay put */
.v2 .hmx-sc{display:grid;grid-template-columns:auto minmax(0,1fr);gap:6px}
.v2 .hmx-days{display:grid;grid-template-rows:repeat(7,1fr);gap:3px;font-size:10px}
