:root[data-style="clean"] .v2 .ib.btx-ib.fill{background:linear-gradient(180deg,var(--btn2-1),var(--btn2-2));box-shadow:var(--btn2-depth);transition:box-shadow var(--t-fast) var(--ease),color var(--t-fast) var(--ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .ib.btx-ib.fill:hover{box-shadow:var(--btn2-hover)}}
:root[data-style="clean"] .v2 .ib.btx-ib.fill:active{box-shadow:var(--btn2-press)}
:root[data-style="clean"] .v2 .pill.soft.btx-pv[aria-pressed="true"]:not([disabled]){background:linear-gradient(180deg,var(--btn2-1),var(--btn2-2));box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--line-strong) 55%,transparent)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .pill.soft.btx-pv[aria-pressed="true"]:not([disabled]):hover{background:linear-gradient(180deg,var(--btn2-1),var(--btn2-2));box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--line-strong) 55%,transparent)}}
:root[data-style="clean"] .v2 .pill.btx-ask.busy:is(.primary,.accent):not([disabled]){color:var(--fg);background:linear-gradient(180deg,var(--btn2-1),var(--btn2-2));box-shadow:var(--btn2-depth);transform:none}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .pill.btx-ask.busy:is(.primary,.accent):not([disabled]):hover{color:var(--fg);background:linear-gradient(180deg,var(--btn2-1),var(--btn2-2));box-shadow:var(--btn2-depth);transform:none}}
:root[data-style="clean"] .v2 .btx-ask::after{display:none}
:root[data-style="clean"] .v2 .pill.btx-ok:active{transform:none}
/* ---------- Badge ---------- */
/* a small label for a plan, an environment or a status. data-tone picks its colour (none is neutral): the accent's tint,
   success, warning and danger, or one of the eight tag colours, each as text on its own tint. Two sizes (.sm), an optional
   dot or icon in front, and an optional remove button after the label. Soft draws it as a pill; Blueprint squares it off,
   sets it in capitals and gives it a hairline in its own colour */
.v2 .bdg{--bdg-bg:var(--chip);--bdg-fg:var(--fg2);display:inline-flex;align-items:center;gap:var(--s-1);max-width:100%;height:24px;padding:0 var(--s-2);border-radius:var(--r-pill);background:var(--bdg-bg);color:var(--bdg-fg);font-size:12.5px;font-weight:500;line-height:1;white-space:nowrap;vertical-align:middle}
.v2 .bdg.sm{height:20px;font-size:11.5px}
.v2 .bdg>.t{min-width:0;overflow:hidden;text-overflow:ellipsis}
.v2 .bdg>.i{flex:none}
/* the dot is the label's own colour, the dark text of its hue, so it keeps 3:1 on the badge's tint (a status's bright mark colour
   would not: the success green is 2.7:1 on its tint) */
.v2 .bdg-dot{position:relative;width:6px;height:6px;border-radius:50%;background:currentColor;flex:none}
/* a live badge (.live: running, streaming, on air) pulses its dot: a soft ring in its own colour grows and fades, on a loop.
   Only transform and opacity move, so it stays on the compositor; with reduced motion the dot stays still */
.v2 .bdg.live .bdg-dot::after{content:"";position:absolute;inset:0;border-radius:inherit;background:inherit;opacity:0;animation:v2-bdgpulse 1.8s cubic-bezier(.22,1,.36,1) infinite}
@keyframes v2-bdgpulse{0%{opacity:.5;transform:scale(1)}100%{opacity:0;transform:scale(2.8)}}
@media (prefers-reduced-motion:reduce){.v2 .bdg.live .bdg-dot::after{animation:none}}
/* a badge you can act on, a removable one or one that is a button or a link, takes a light hover: a little more of its own
   colour in its tint, its words leaning a little toward the text colour so they keep 4.5:1 and APCA 60 on the deeper tint.
   Plain labels keep still, so they never look clickable */
.v2 .bdg:is(:has(>.bdg-x),button,a[href]){transition:background var(--t-fast),color var(--t-fast)}
.v2 .bdg:is(button,a[href]){cursor:pointer;text-decoration:none}
@media (hover:hover) and (pointer:fine){.v2 .bdg:is(:has(>.bdg-x),button,a[href]):hover{background:color-mix(in srgb,var(--bdg-fg) 7%,var(--bdg-bg));color:color-mix(in srgb,var(--bdg-fg) 85%,var(--fg))}}
/* on the Badge card every badge answers the pointer: a hand, a light hover, and no text selection. On the hover's deeper tint
   the label leans a little toward the text colour, as on a menu row, so it keeps 4.5:1 and Lc 60 */
.v2 .bdx .bdg{cursor:pointer;user-select:none;-webkit-user-select:none;transition:background var(--t-fast),color var(--t-fast)}
@media (hover:hover) and (pointer:fine){.v2 .bdx .bdg:hover,.v2 .bdg:has(>.bdg-x):hover{background:color-mix(in srgb,var(--bdg-fg) 7%,var(--bdg-bg));color:color-mix(in srgb,var(--bdg-fg) 85%,var(--fg))}}
.v2 .bdg[data-tone="accent"]{--bdg-bg:var(--accent-bg);--bdg-fg:var(--accent-fg)}
.v2 .bdg[data-tone="success"]{--bdg-bg:var(--ok-bg);--bdg-fg:var(--ok)}.v2 .bdg[data-tone="warning"]{--bdg-bg:var(--warn-bg);--bdg-fg:var(--warn)}.v2 .bdg[data-tone="danger"]{--bdg-bg:var(--bad-bg);--bdg-fg:var(--bad)}
.v2 .bdg[data-tone="blue"]{--bdg-bg:var(--pb-bg);--bdg-fg:var(--pb)}.v2 .bdg[data-tone="violet"]{--bdg-bg:var(--pl-bg);--bdg-fg:var(--pl)}.v2 .bdg[data-tone="green"]{--bdg-bg:var(--pm-bg);--bdg-fg:var(--pm)}.v2 .bdg[data-tone="orange"]{--bdg-bg:var(--pp-bg);--bdg-fg:var(--pp)}
.v2 .bdg[data-tone="red"]{--bdg-bg:var(--pr-bg);--bdg-fg:var(--pr)}.v2 .bdg[data-tone="yellow"]{--bdg-bg:var(--py-bg);--bdg-fg:var(--py)}.v2 .bdg[data-tone="pink"]{--bdg-bg:var(--pk-bg);--bdg-fg:var(--pk)}.v2 .bdg[data-tone="teal"]{--bdg-bg:var(--pt-bg);--bdg-fg:var(--pt)}
/* the remove button sits inside the badge's end; its hover is a little more of the badge's own colour */
.v2 .bdg-x{display:grid;place-items:center;width:16px;height:16px;margin-right:calc(var(--s-1) * -1);border-radius:50%;color:inherit;flex:none;transition:background var(--t-fast)}
@media (hover:hover) and (pointer:fine){.v2 .bdg-x:hover{background:color-mix(in srgb,currentColor 12%,transparent)}}
.v2 .bdg-x:focus-visible{outline-offset:1px;border-radius:50%}
.v2 .bdg.sm .bdg-x{width:14px;height:14px}
/* on a hovered menu row's tint (a step lighter in dark mode) the label leans a little toward the text colour, so it keeps APCA 60 */
.v2 .mi.hl .bdg{color:color-mix(in srgb,var(--bdg-fg) 85%,var(--fg))}
@media (hover:hover) and (pointer:fine){.v2 .mi:hover .bdg{color:color-mix(in srgb,var(--bdg-fg) 85%,var(--fg))}}
.v2 .bdg.go{animation:v2-bdgout .22s var(--ease) forwards}
@keyframes v2-bdgout{to{opacity:0;transform:scale(.85)}}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .bdg{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--bdg-fg) 14%,transparent);font-size:11px;letter-spacing:.03em;text-transform:uppercase}
:root:not([data-style="soft"],[data-style="clean"]) .v2 .bdg.sm{font-size:10.5px}
/* Blueprint's lime tint is faint on white, so an accent badge's edge is the accent's mark */
:root:not([data-style="soft"],[data-style="clean"]) .v2 .bdg[data-tone="accent"]{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent-mark) 50%,transparent)}
/* Clean: the neutral badge is a see-through grey, so it shows on whatever it sits on (Clean's chip grey is the stage's own) */
:root[data-style="clean"] .v2 .bdg:not([data-tone]){--bdg-bg:color-mix(in srgb,var(--fg) 7%,transparent)}
/* the card: each kind of badge in a row, named on the left */
.v2 .bdx{width:100%;display:flex;flex-direction:column;gap:var(--s-4);container:bdx/inline-size}
/* a row's name sits on the line of its first badges, so a set that wraps to a second line keeps its name at the top */
.v2 .bdx-row{display:flex;align-items:flex-start;gap:var(--s-2)}
.v2 .bdx-l{width:76px;flex:none;font-size:12px;line-height:24px}
.v2 .bdx-set{flex:1;min-width:0;display:flex;flex-wrap:wrap;align-items:center;gap:var(--s-2)}
.v2 .pill.bdx-undo{height:24px}
.v2 .bdx-live{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@container bdx (max-width:360px){.v2 .bdx-row{flex-direction:column;align-items:flex-start;gap:var(--s-2)}.v2 .bdx-l{width:auto}.v2 .bdx-set{width:100%}}
/* ---------- Tooltip ---------- */
/* a toolbar of icon buttons whose labels (the core tooltip, data-tip) wait a moment, then follow the pointer from button to
   button, and the people at its end, each opening a card about them on hover or keyboard focus. The component is the toolbar:
   the card opens over the stage, so it keeps no room for it */
.v2 .ttp{position:relative;display:flex;flex-direction:column;align-items:center}
.v2 .ttp-bar{display:flex;align-items:center;gap:2px;padding:5px;border-radius:var(--r-pill)}
.v2 .ttp-sep{width:1px;height:18px;background:var(--line);margin:0 var(--s-1)}
/* the people side by side, never stacked over each other (owner, 18 Nov) */
.v2 .ttp-avs{display:flex;gap:2px}
/* a person under the pointer stays where they are (owner, 21 Nov: "you hover it up but show tooltip down"): the one quiet hover
   fill, a ring in their round shape, easing in and out */
.v2 .ttp-av{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;transition:background-color var(--t-fast) var(--ease),box-shadow var(--t-fast) var(--ease)}
@media (hover:hover) and (pointer:fine){.v2 .ttp-av:hover{background:var(--row);box-shadow:0 0 0 2px var(--row)}}
.v2 .ttp-av .av{width:28px;height:28px;font-size:11px}
/* the card about a person: centred on their avatar (right-aligned to it at the stage's edge), under it when there is room and
   over it when there isn't, and it goes where the avatar goes while it shows (placed by the script) */
.v2 .ttp-card{position:absolute;top:0;left:0;width:230px;padding:var(--s-3);box-shadow:var(--shadow-pop);opacity:0;transform:translateY(6px) scale(.97);filter:blur(4px);pointer-events:none;transition:opacity .25s var(--ease),transform .35s var(--ease),filter .25s;z-index:5}
/* the card opens from the avatar toward where it shows: down from it when it opens under it, up from it when it opens over it */
.v2 .ttp-card:not(.up){transform:translateY(-6px) scale(.97);transform-origin:50% 0}
.v2 .ttp-card.up{transform:translateY(6px) scale(.97);transform-origin:50% 100%}
.v2 .ttp-card.show{opacity:1;transform:none;filter:none}
.v2 .ttp-ch{display:flex;align-items:center;gap:10px}
.v2 .ttp-ch .av{width:34px;height:34px;font-size:12px}
.v2 .ttp-ch div{display:flex;flex-direction:column;min-width:0;font-size:13px}
.v2 .ttp-ch b{font-weight:500}
.v2 .ttp-ch div span{font-size:12px;color:var(--muted)}
.v2 .ttp-cs{display:flex;align-items:center;gap:6px;margin-top:10px;font-size:12px;color:var(--fg2)}
.v2 .ttp-cs .dot{color:var(--ok-mark)}
/* Clean: the card's content 16px in from every edge (owner, 18 Nov); it scales and fades in, never blurs */
:root[data-style="clean"] .v2 .ttp-card.panel{width:246px;padding:16px;filter:none;transition:opacity var(--t-fast) var(--ease),transform var(--t) var(--ease)}
/* Clean (owner, 21 Nov): the bar, as Canvas toolbar's, is a pill drawn by a half-strength hairline with only a contact shadow,
   its dividers half-strength hairlines, and its hovers pills (a circle round a person, with its ring) under one gliding highlight
   (hoverGlide). The card about a person is Clean's popover, 22px corners and its shadow, with what they are doing now in an
   off-white foot strip under a hairline, edge to edge, its words 16px in */
:root[data-style="clean"] .v2 .ttp-bar.panel{box-shadow:0 0 0 1px var(--hair),0 1px 2px rgba(0,0,0,.06)}
:root[data-style="clean"] .v2 .ttp-sep{background:color-mix(in srgb,var(--line) 50%,transparent)}
:root[data-style="clean"] .v2 .ttp-cs{margin:16px -16px -16px;padding:12px 16px;line-height:16px;background:var(--strip);border-top:1px solid var(--line);border-radius:0 0 var(--r-card) var(--r-card)}
/* ---------- Search input ---------- */
/* one field, as wide as the other single fields (the full width on a phone), with its suggestions in a list that opens from
   it: under it, or over it when the room under it is too short (placePop). Its script keeps the field and the open list
   centred in the stage together, the field gliding up as the list opens (centre()); no room is kept for the list. The
   field's glass, the rows' icons, the answer's spark and the group names share one column 12px in, and the words another */
.v2 .six{position:relative;width:100%;max-width:var(--field-w);margin:0 auto}
.v2 .six-box{background:var(--surface);border-radius:var(--r-field);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line) 50%,transparent);transition:box-shadow var(--t-fast)}
@supports (corner-shape:squircle){.v2 .six-box{corner-shape:squircle;border-radius:var(--r-field-sq)}}
/* the edge steps up while the field is in use (it has the focus, or the preview types in it); nothing else changes */
.v2 .six-box.f{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line-strong) 50%,transparent)}
.v2 .six-in{display:flex;align-items:center;gap:var(--s-2);height:var(--field-h);padding:0 var(--s-2) 0 var(--s-3);color:var(--muted)}
.v2 .six-in input{flex:1;min-width:0;height:100%;border:0;outline:0;background:transparent;font:inherit;font-size:13.5px;color:var(--fg)}
/* (its words start right after the glass, as the rows' words do) */
.v2 .six .six-in input{padding:0}
.v2 .six-in input::placeholder{color:var(--muted)}
.v2 .six-chips{display:flex;gap:var(--s-1)}
.v2 .six-chips:empty{display:none}
.v2 .six-ch{display:inline-flex;align-items:center;gap:2px;height:24px;padding:0 2px 0 var(--s-2);border-radius:var(--r-tag);background:var(--accent-bg);color:var(--accent-fg,var(--accent));font-size:12px;font-weight:500;white-space:nowrap}
.v2 .six-ch button{width:20px;height:20px;border-radius:50%;display:grid;place-items:center;opacity:.7;transition:opacity var(--t-fast),background var(--t-fast)}
@media (hover:hover) and (pointer:fine){.v2 .six-ch button:hover{opacity:1;background:color-mix(in srgb,currentColor 12%,transparent)}}
@supports (corner-shape:squircle){.v2 .six-ch{corner-shape:squircle;border-radius:var(--r-tag-sq)}}
/* the key hint and the clear button's cross end 14px in, where the rows' sources end */
.v2 .six-k{margin-right:6px}
.v2 .six-x{width:24px;height:24px}
/* nothing in it grows or shrinks when pressed */
.v2 .six :is(.ib,.pill):active,:root[data-style="clean"] .v2 .six .ib:active{transform:none}
/* the list: one family with the field (owner, 21 Nov: "the input is different shape than the dropdown"): as wide as it, 6px
   under it, with the field's corners. Its rows sit 6px in, their corners the list's less those 6px, so their icons and words
   fall on the field's columns and their sources end where the field's cross does. (The 6px are the results' own padding, so
   the answer above them can run to the list's edges) */
.v2 .six-pop{left:0;right:0;min-width:0;padding:0;border-radius:var(--r-field)}
@supports (corner-shape:squircle){.v2 .six-pop{border-radius:var(--r-field-sq)}}
.v2 .six-res{position:relative;padding:6px}
.v2 .six-g{font-size:11.5px;color:var(--muted);padding:var(--s-2) var(--s-2) var(--s-1) 6px}
.v2 .six-it{display:flex;align-items:center;gap:var(--s-2);width:100%;padding:7px var(--s-2) 7px 6px;border-radius:calc(var(--r-field) - 4px);font-size:13px;text-align:left;transition:background .15s}
@supports (corner-shape:squircle){.v2 .six-it{border-radius:calc(var(--r-field-sq) - 6px)}}
.v2 .six-it.hl{background:var(--row)}
@media (hover:hover) and (pointer:fine){.v2 .six-it:hover{background:var(--row)}}
.v2 .six-it .ic{color:var(--muted);display:grid;flex:none}
.v2 .six-it .d{margin-left:auto;padding-left:var(--s-2);font-size:12px;color:var(--muted);transition:color .15s}
/* on a highlighted row's grey the source steps up, so it keeps 4.5:1 and APCA Lc 60 in dark mode */
@media (hover:hover) and (pointer:fine){.v2 .six-it:is(:hover,.hl) .d{color:var(--fg2)}}
.v2 .six-it mark{background:transparent;color:var(--accent-fg,var(--accent));font-weight:500}
/* the agent's answer is the list's head section (owner, 21 Nov: "too stark"): no box and no tint, running to the list's edges
   with a hairline under it. Its spark is on the icons' column, in the accent's mark colour, the only colour in it; its words
   are on the words' column, in the text colour at the rows' size. It grows with the list as its words come in. Clean makes
   it the list's off-white head strip, with the spark muted */
.v2 .six-ans{display:flex;gap:var(--s-2);margin:-6px -6px 6px;padding:10px 14px 10px 12px;border-bottom:1px solid color-mix(in srgb,var(--line) 50%,transparent);font-size:13px;line-height:1.5;color:var(--fg)}
.v2 .six-ans>svg{color:var(--accent-mark);flex:none;margin-top:3px}
.v2 .six-ans .w{animation:v2-sxw .4s var(--ease) both}
.v2 .six-ans .w.done{animation:none}
@keyframes v2-sxw{from{opacity:0;filter:blur(3px)}}
@keyframes v2-sxwc{from{opacity:0}}
/* Clean: the list has the field's 10px corners and its rows follow them, 6px in (4px corners); the answer is the off-white
   head strip under the list's top corners, with a full hairline under it; the rows' hover is Clean's quiet fill at its own
   ease; the filter is a tag with rounded corners, not a pill; new words fade in without a blur */
:root[data-style="clean"] .v2 .six-it{border-radius:calc(var(--r-field) - 6px);transition:background-color var(--t-fast) var(--ease)}
:root[data-style="clean"] .v2 .six-ans{background:var(--strip);border-bottom-color:var(--line);border-radius:var(--r-field) var(--r-field) 0 0}
:root[data-style="clean"] .v2 .six-ans>svg{color:var(--muted)}
:root[data-style="clean"] .v2 .six-ch{border-radius:var(--r-sm)}
:root[data-style="clean"] .v2 .six-ans .w:not(.done){animation-name:v2-sxwc;animation-duration:var(--t)}
/* ---------- Country select ---------- */
/* the label, the field and the hint, as wide as the other single fields. The list opens from the field (placePop), and the
   field glides up with it so the two sit centred together (centre()). The field's flag, the search's glass and the rows'
   flags share one column 12px in, and the names another; the currencies end 12px in, before the chosen country's tick */
.v2 .csx{width:100%;max-width:var(--field-w);margin:0 auto;display:flex;flex-direction:column;gap:6px;position:relative}
.v2 .csx-l{font-size:12.5px;font-weight:500}
.v2 .csx-f{display:flex;align-items:center;gap:10px;height:var(--field-h);padding:0 var(--s-3);border-radius:var(--r-field);background:var(--surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line) 50%,transparent);font-size:13.5px;text-align:left;transition:box-shadow var(--t-fast)}
@supports (corner-shape:squircle){.v2 .csx-f{corner-shape:squircle;border-radius:var(--r-field-sq)}}
/* a dropdown's field steps up its edge while it has the keyboard's focus or its list is open; it takes no ring */
.v2 .csx-f:focus-visible{outline:0}
.v2 .csx-f:is(:focus-visible,[aria-expanded="true"]){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line-strong) 50%,transparent)}
.v2 .csx-v{flex:1}
.v2 .csx-f>svg{color:var(--muted);transition:transform .35s var(--ease)}
.v2 .csx-f[aria-expanded="true"]>svg{transform:rotate(180deg)}
.v2 .csx-fl{display:grid;place-items:center;flex:none;width:20px}
.v2 .csx-h{font-size:12px;transition:opacity var(--t-fast) var(--ease)}
/* the open list covers the hint under the field, so the hint steps aside rather than peeking out at the list's corner */
.v2 .csx:has(.csx-pop.open) .csx-h{opacity:0}
/* closed, the list is hidden as well as clear (.pop), so Tab passes over its search and its countries */
.v2 .csx-pop{left:0;right:0;min-width:0;padding:0 6px 6px}
/* the search is the list's first row: its glass on the flags' column, its words on the names', a hairline under it that
   steps up while it has the focus */
.v2 .csx-s{display:flex;align-items:center;gap:10px;height:var(--field-h);margin:0 -6px 6px;padding:0 var(--s-3);border-bottom:1px solid color-mix(in srgb,var(--line) 50%,transparent);color:var(--muted);transition:border-color var(--t-fast)}
.v2 .csx-s>svg{margin:0 4px}
.v2 .csx-s:has(.csx-q:focus){border-bottom-color:color-mix(in srgb,var(--field-line-strong) 50%,transparent)}
.v2 .csx-q{flex:1;min-width:0;height:100%;border:0;outline:0;background:transparent;padding:0;font:inherit;font-size:13px;color:var(--fg)}
.v2 .csx-q::placeholder{color:var(--muted)}
.v2 .csx-list{max-height:200px;overflow-y:auto;display:flex;flex-direction:column;gap:2px}
.v2 .csx-o{display:flex;align-items:center;gap:10px;padding:7px 6px;border-radius:calc(9px * var(--rk-m,var(--rk)));font-size:13px;text-align:left;flex:none;transition:background var(--t-fast)}
.v2 .csx-o.hl{background:var(--row)}
.v2 .csx-o .cd{margin-left:auto;font-size:11.5px;color:var(--muted);transition:color var(--t-fast)}
/* on a highlighted row's grey the currency steps up, so it keeps 4.5:1 and APCA Lc 60 in dark mode */
.v2 .csx-o.hl .cd{color:var(--fg2)}
/* every row keeps a place for the tick, so the currencies stand in one column */
.v2 .csx-o .ck{display:grid;color:var(--accent-fg,var(--accent));visibility:hidden}
.v2 .csx-o[aria-selected="true"] .ck{visibility:visible}
.v2 .csx-g{font-size:11.5px;color:var(--muted);padding:6px 6px 2px}
/* Clean (owner, 21 Nov: "almost no difference between soft and clean so make it clearer"). The field is a flat dropdown
   trigger: an off-white fill under a hairline that deepens on hover and while its list is open. The list opens from it with
   Clean's scale and fade, in the menus' 22px corners: its search sits in an off-white head strip, "Suggested" is Clean's
   section label, and the rows are 10px with the one gliding highlight (hoverGlide). The flags, the glass and the label stand
   on one column 16px in; the codes end on the content's right edge, 16px in, and the picked row keeps a stronger fill and its
   tick, in the accent (white in dark), in a column of its own just before its code */
:root[data-style="clean"] .v2 .csx-f{background:var(--strip);box-shadow:var(--btn2-depth);transition:box-shadow var(--t-fast) var(--ease),background-color var(--t-fast) var(--ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .csx-f:hover{background:var(--chip);box-shadow:var(--btn2-hover)}}
:root[data-style="clean"] .v2 .csx-f:is(:focus-visible,[aria-expanded="true"]){background:var(--chip);box-shadow:var(--btn2-hover)}
:root[data-style="clean"] .v2 .csx-f>svg{transition:transform var(--t) var(--ease)}
:root[data-style="clean"] .v2 .csx-pop{border-radius:var(--r-card);padding:0 6px 6px}
:root[data-style="clean"] .v2 .csx-s{height:44px;margin:0 -6px 4px;padding:0 16px;background:var(--strip);border-bottom:1px solid var(--line);border-radius:var(--r-card) var(--r-card) 0 0}
:root[data-style="clean"] .v2 .csx-s:has(.csx-q:focus){border-bottom-color:var(--line)}
:root[data-style="clean"] .v2 .csx-list{gap:2px;max-height:227px}
:root[data-style="clean"] .v2 .csx-g{padding:10px 10px 4px;font-size:11.5px;line-height:16px;color:var(--muted)}
:root[data-style="clean"] .v2 .csx-o{height:34px;padding:0 10px;border-radius:10px;transition:background-color var(--t-fast) var(--ease)}
:root[data-style="clean"] .v2 .csx-o[aria-selected="true"]{background:var(--row-on)}
:root[data-style="clean"] .v2 .csx-o .ck{order:1;margin-left:auto}
:root[data-style="clean"] .v2 .csx-o .cd{order:2;margin-left:8px;min-width:28px;text-align:right}
/* (on the picked row's stronger grey the code steps up, so it keeps 4.5:1) */
:root[data-style="clean"] .v2 .csx-o[aria-selected="true"] .cd{color:var(--fg2)}
/* ---------- Multi-select ---------- */
/* a combobox that keeps what you pick as chips: typing filters the list, the arrows move through it, Enter picks or
   unpicks, Escape closes it, and Backspace in an empty box takes the last chip off. As wide as the other single fields; the
   list opens from the box (placePop) and the box glides up with it, so the two sit centred together (centre()). The rows'
   checkboxes stand on the column the box's words start on, 12px in, and their counts end 12px in */
.v2 .msc{position:relative;width:100%;max-width:var(--field-w);margin:0 auto;display:flex;flex-direction:column;gap:6px}
.v2 .msc-top{display:flex;align-items:center;justify-content:space-between;gap:var(--s-2);min-height:22px}
.v2 .msc-l{font-size:12.5px;font-weight:500}
.v2 .msc-clr{height:22px;padding:0 6px;margin-right:-6px;border-radius:calc(6px * var(--rk-s,var(--rk)));font-size:12px;color:var(--muted);transition:color .2s,background .2s}
@media (hover:hover) and (pointer:fine){.v2 .msc-clr:hover{color:var(--fg);background:var(--row)}}
/* (its chips and its text box are all 26px tall: the lines they wrap onto are centred in the box) */
.v2 .msc-f{position:relative;display:flex;flex-wrap:wrap;align-items:flex-start;align-content:center;gap:6px;min-height:var(--field-h);padding:6px;border-radius:var(--r-field);background:var(--surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line) 50%,transparent);cursor:text;transition:box-shadow var(--t-fast)}
@supports (corner-shape:squircle){.v2 .msc-f{corner-shape:squircle;border-radius:var(--r-field-sq)}}
/* the edge steps up while its search box has the focus or its list is open; a tag's remove button rings on its own, never
   inside the field */
.v2 .msc-f:has(.msc-q:focus),.v2 .msc:has(.msc-pop.open) .msc-f{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line-strong) 50%,transparent)}
.v2 .msc-q{flex:1;min-width:80px;height:26px;border:0;outline:0;background:transparent;padding:0 6px;font:inherit;font-size:13.5px;color:var(--fg)}
.v2 .msc-q::placeholder{color:var(--muted)}
.v2 .msc-c{display:inline-flex;align-items:center;gap:2px;height:26px;padding:0 3px 0 var(--s-2);border-radius:var(--r-tag);background:var(--chip);font-size:12.5px;white-space:nowrap}
@supports (corner-shape:squircle){.v2 .msc-c{corner-shape:squircle;border-radius:var(--r-tag-sq)}}
.v2 .msc-c button{width:20px;height:20px;border-radius:50%;display:grid;place-items:center;color:var(--muted);transition:background .2s,color .2s}
@media (hover:hover) and (pointer:fine){.v2 .msc-c button:hover{background:color-mix(in srgb,currentColor 12%,transparent);color:var(--fg)}}
.v2 .msc-c.go{animation:v2-mscout .22s var(--ease) forwards}
@keyframes v2-mscout{to{opacity:0;transform:scale(.85)}}
/* the key just pressed, while the preview plays, at the end of the line the cursor is on */
.v2 .msc-key{position:absolute;right:8px;bottom:10px;opacity:0;transition:opacity .2s}
.v2 .msc-key.on{opacity:1}
.v2 .msc-pop{left:0;right:0;min-width:0}
/* (the rows are placed against the list itself, so keeping the highlighted one in view scrolls by the list's own measure) */
.v2 .msc-list{position:relative;max-height:210px;overflow-y:auto;display:flex;flex-direction:column;gap:2px}
.v2 .msc-o{display:flex;align-items:center;gap:10px;min-height:34px;padding:6px;border-radius:calc(9px * var(--rk-m,var(--rk)));font-size:13px;cursor:pointer;flex:none;transition:background var(--t-fast)}
.v2 .msc-o.hl{background:var(--row)}
.v2 .msc-o .bx{width:16px;height:16px;border-radius:var(--r-tiny,5px);box-shadow:inset 0 0 0 1.5px var(--fg2);display:grid;place-items:center;color:transparent;flex:none;transition:background .2s,box-shadow .2s,color .2s}
.v2 .msc-o[aria-selected="true"] .bx{background:var(--accent);box-shadow:inset 0 0 0 1px var(--accent-mark,var(--accent));color:var(--on-accent,#fff)}
.v2 .msc-o .n{margin-left:auto;font-size:12px;color:var(--muted);transition:color var(--t-fast)}
/* on a highlighted row's grey the count steps up, so it keeps 4.5:1 and APCA Lc 60 in dark mode */
.v2 .msc-o.hl .n{color:var(--fg2)}
.v2 .msc-none{padding:var(--s-2) 6px;font-size:12.5px;color:var(--muted)}
.v2 .msc-h{font-size:12px;transition:opacity var(--t-fast) var(--ease)}
/* the open list covers the hint under the box, so the hint steps aside instead of peeking out above the list */
.v2 .msc:has(.msc-pop.open) .msc-h{opacity:0}
/* Clean: the chips are tags with rounded corners, not pills; the list has the menus' 22px corners and its rows follow them;
   a checkbox is a rounded square with an inner shadow, ink once ticked (as Permission gate's) */
:root[data-style="clean"] .v2 .msc-c{border-radius:var(--r-sm)}
:root[data-style="clean"] .v2 .msc-pop{border-radius:var(--r-card)}
:root[data-style="clean"] .v2 .msc-o{border-radius:calc(var(--r-card) - 6px)}
:root[data-style="clean"] .v2 .msc-o .bx{border-radius:calc(3px * var(--rk-s,var(--rk)));background:var(--surface);box-shadow:inset 0 0 0 1.5px var(--fg2),var(--track-ring)}
:root[data-style="clean"] .v2 .msc-o[aria-selected="true"] .bx{background:linear-gradient(180deg,var(--btn-1),var(--btn-2));box-shadow:inset 0 0 0 1px var(--btn-2),inset 0 2px 3px -1px rgba(255,255,255,.28);color:var(--on-btn)}
/* ---------- Social sign-in ---------- */
/* its content 16px in from every edge (owner, 18 Nov). Each provider is a secondary button as tall as a field, its mark and
   its words on the same two columns in every button; the one used last has a stronger edge and a plain grey Last used tag at
   its end, inside it. Signing in, the card eases to the welcome's height (grow()) */
.v2 .ssi{padding:var(--s-4);display:flex;flex-direction:column;align-items:center;gap:14px;max-width:320px;margin:0 auto;width:100%}
.v2 .ssi>.dm-grow{align-self:stretch;align-items:center}
.v2 .ssi-h{display:flex;flex-direction:column;align-items:center;gap:var(--s-3);text-align:center}
.v2 .ssi-lg{width:44px;height:44px;border-radius:calc(14px * var(--rk-l,var(--rk)));background:var(--ink);color:var(--on-ink);display:grid;place-items:center}
.v2 .ssi-lg .logo{width:26px;height:26px}
.v2 .ssi-h b{font-weight:500;font-size:14px}
.v2 .ssi-list{display:flex;flex-direction:column;gap:var(--s-2);width:100%;container:ssi/inline-size}
/* each provider's mark and words are centred together in its button, 8px apart, as the card centres everything else (owner,
   21 Nov: "why are these not center aligned?"); the marks are one size, on the words' centre line */
.v2 .ssi-b{position:relative;display:flex;align-items:center;justify-content:center;gap:var(--s-2);width:100%;height:var(--field-h);padding:0 var(--s-4);border-radius:var(--r-pill);background:var(--surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--rail) 50%,transparent);font-size:13.5px;font-weight:500;text-align:center;transition:background var(--t-fast),box-shadow var(--t-fast),opacity var(--t-fast)}
@media (hover:hover) and (pointer:fine){.v2 .ssi-b:hover{background:var(--wash);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--faint) 50%,transparent)}}
.v2 .ssi-b .mk{width:18px;height:18px;display:grid;place-items:center;flex:none}
.v2 .ssi-b .mk svg,.v2 .ssi-b .mk img{width:18px;height:18px;display:block}
.v2 .ssi-b .mk .i{width:16px;height:16px}
.v2 .ssi-b .mk .lt{min-width:18px;height:18px;padding:0 3px;border-radius:var(--r-tiny,5px);background:var(--ink);color:var(--on-ink);display:grid;place-items:center;font-size:10px;font-weight:500}
.v2 .ssi-b .lb{flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
/* Last used sits apart at the right end of its button, so its words stay centred like the others'. That button keeps the
   tag's room on both sides of its words, and where "Continue with" and its name don't fit between (a button under 340px) it
   says only the provider's name */
.v2 .ssi-b .last{position:absolute;right:10px;top:50%;transform:translateY(-50%)}
.v2 .ssi-b.last-used{container:ssib/inline-size;padding-inline:88px}
@container ssib (max-width:339px){.v2 .ssi-b .lb .pre{display:none}}
/* on a narrow phone the buttons say only the provider's name, so the one used last keeps its whole name beside its tag (each
   button keeps "Continue with …" as its name for screen readers) */
@container ssi (max-width:259px){.v2 .ssi-b .lb .pre{display:none}}
.v2 .ssi-b.last-used{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--pick-on) 50%,transparent)}
/* nothing in it grows or shrinks when pressed */
.v2 .ssi .pill:active{transform:none}
.v2 .ssi-b.busy{pointer-events:none}
.v2 .ssi-list.wait .ssi-b:not(.busy){opacity:.45}
.v2 .ssi-or{display:flex;align-items:center;gap:10px;width:100%;font-size:11.5px;color:var(--muted)}
.v2 .ssi-or::before,.v2 .ssi-or::after{content:"";flex:1;height:1px;background:color-mix(in srgb,var(--line) 50%,transparent)}
/* its words end 16px over the card's foot; the hover fill reaches out round them */
.v2 .ssi-mail{font-size:12.5px;color:var(--fg2);padding:var(--s-1) 10px;margin-bottom:calc(-1 * var(--s-1));border-radius:var(--r-pill);transition:color .2s,background .2s}
@media (hover:hover) and (pointer:fine){.v2 .ssi-mail:hover{color:var(--fg);background:var(--row)}}
.v2 .ssi-ok{display:flex;flex-direction:column;align-items:center;gap:var(--s-2);width:100%;padding:var(--s-2) 0 var(--s-1);text-align:center;font-size:13px}
.v2 .ssi-ok .av{width:44px;height:44px;font-size:14px}
/* Clean: the providers are its flat secondaries (a hairline and a light fill that deepens a little on hover and press);
   the one used last has a stronger hairline */
:root[data-style="clean"] .v2 .ssi-b{background:linear-gradient(180deg,var(--btn2-1),var(--btn2-2));box-shadow:var(--btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .ssi-b:hover{box-shadow:var(--btn2-hover)}}
:root[data-style="clean"] .v2 .ssi-b:active{box-shadow:var(--btn2-press)}
:root[data-style="clean"] .v2 .ssi-b.last-used{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--fg) 26%,transparent)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .ssi-b.last-used:hover{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--fg) 30%,transparent),inset 0 0 0 99px color-mix(in srgb,var(--fg) 2.5%,transparent)}}
/* ---------- Sign in ---------- */
/* its content 16px in from every edge (owner, 18 Nov). The card grows and shrinks with each step, so it keeps no room for a
   later one: the code arriving, a message under the field, the shorter confirmation. The steps (.sgx-body) and the foot each
   ease their own height (grow()), and the card is always the two together: the foot stays at the card's bottom edge with its
   corners at every frame, and only the steps are clipped while they ease, top to bottom (owner, 21 Nov). The title block, the
   boxes and the line under them are 12px apart */
.v2 .sgx{padding:var(--s-4);max-width:320px;margin:0 auto;width:100%}
.v2 .sgx-body.growing{overflow-x:visible}
.v2 .sgx-st{display:flex;flex-direction:column;gap:6px}
.v2 .sgx-st>b{font-weight:500;font-size:14px}
.v2 .sgx-st>.muted{font-size:12.5px;margin-bottom:6px}
.v2 .sgx-st.in{animation:v2-sgin .5s var(--ease) both}
@keyframes v2-sgin{from{opacity:0;transform:translateX(20px);filter:blur(4px)}}
.v2 .sgx-f{display:flex;flex-direction:column;gap:5px;font-size:12.5px;font-weight:500}
.v2 .sgx-f input{height:var(--field-h);border:0;outline:0;border-radius:var(--r-field);background:var(--surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line) 50%,transparent);padding:0 var(--s-3);font:inherit;font-size:13.5px;font-weight:400;color:var(--fg);transition:box-shadow var(--t-fast)}
@supports (corner-shape:squircle){.v2 .sgx-f input{corner-shape:squircle;border-radius:var(--r-field-sq)}}
.v2 .sgx-f input::placeholder{color:var(--muted)}
.v2 .sgx-f input:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line-strong) 50%,transparent)}
/* a field marked wrong keeps its red edge, focused or not, until it is fixed; the line under it says what is wrong in red
   words after the alert mark, with no red fill, and opens and closes rather than keeping room for itself */
.v2 .sgx-f.bad input{box-shadow:inset 0 0 0 1px var(--bad);animation:v2-sgsh .4s}
@keyframes v2-sgsh{20%,60%{transform:translateX(-4px)}40%,80%{transform:translateX(4px)}}
/* (a shut line adds nothing under the field: the fold takes back the step's 6px gap, and the open line brings its own) */
.v2 .sgx-ef{margin-top:-6px}
.v2 .sgx-err{display:flex;align-items:center;gap:6px;padding-top:6px;font-size:12px;color:var(--bad)}
.v2 .sgx-err>svg{flex:none;color:var(--bad-mark,var(--bad))}
/* nothing in it grows or shrinks when pressed but Clean's ink primary */
.v2 .sgx .pill:active{transform:none}
/* the foot: the step's action or the line that says how it is going (Send code, then the resend line, Verifying code, a
   wrong code or Code confirmed, then the workspace opening). It is one foot for every step, so it keeps its place as the
   steps change: 12px under the step in Soft and Blueprint, and Clean's foot strip (below). Send code is as wide as the field */
.v2 .sgx-ft{margin-top:var(--s-3)}
.v2 .sgx-go{height:var(--field-h);width:100%}
/* the back link's chevron sits on the content's edge, as the words under it do */
.v2 .sgx-bk{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--muted);align-self:flex-start;margin:0 0 6px -4px}
@media (hover:hover) and (pointer:fine){.v2 .sgx-bk:hover{color:var(--fg)}}
.v2 .sgx-code{display:grid;grid-template-columns:repeat(6,1fr);gap:6px}
/* the boxes: every box, filled or not, has the one fill and the one dimmed edge; the focused box, or with none focused the
   next one to fill, has the field's focus edge. While the code is checked all six dim a little, together, and the line under
   them says so (owner, 21 Nov: no wave across them) */
.v2 .sgx-code input{width:100%;height:var(--field-h);border:0;outline:0;border-radius:var(--r-field);background:var(--surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line) 50%,transparent);text-align:center;font:inherit;font-size:14px;font-variant-numeric:tabular-nums;color:var(--fg);transition:box-shadow var(--t-fast),opacity var(--t-fast),transform .3s var(--ease)}
@supports (corner-shape:squircle){.v2 .sgx-code input{corner-shape:squircle;border-radius:var(--r-field-sq)}}
.v2 .sgx-code input:focus,.v2 .sgx-code:not(:focus-within) input.nx{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line-strong) 50%,transparent)}
.v2 .sgx-code input.f{transform:scale(1.04)}
/* the code as it arrives (owner, 21 Nov: no card in the card): a quiet chip under the boxes, the way a phone offers a
   one-time code, "From Mail 482 157". Pressed, it fills every box and goes. It folds open when the email arrives, so the card
   grows smoothly for it and keeps no room before */
.v2 .sgx-af{margin-top:-6px}
.v2 .sgx-sug{display:flex;width:fit-content;margin-top:var(--s-3)}
.v2 .sgx-sug .num{color:var(--fg);font-weight:500}
.v2 .sgx-code input{caret-color:var(--accent-fg,var(--accent))}
.v2 .sgx-code.vf input{opacity:.7}
/* a wrong code: the boxes clear with a red edge and shake (not with reduced motion) until typing starts over */
.v2 .sgx-code.bad input{box-shadow:inset 0 0 0 1px var(--bad)}
.v2 .sgx-code.bad{animation:v2-sgsh .4s}
@media (prefers-reduced-motion:reduce){.v2 .sgx-code.bad,.v2 .sgx-f.bad input{animation:none}}
/* the line under the boxes: what runs is said with the highlight sweep; a confirmed code is the green tick and plain words */
.v2 .sgx-v{display:inline-flex;align-items:center;gap:7px;color:var(--fg2)}
.v2 .sgx-rs>.sgx-v{display:flex;min-height:inherit}
.v2 .sgx-v .spin{width:11px;height:11px}
.v2 .sgx-v .shim{font-size:inherit}
.v2 .sgx-v.ok .i{color:var(--ok-mark)}
.v2 .sgx-v.bad{color:var(--bad)}
.v2 .sgx-v.bad .i{color:var(--bad-mark,var(--bad))}
.v2 .sgx-hint{color:var(--fg2)}
.v2 .sgx-re{color:var(--accent-fg,var(--accent));font-weight:500;font-size:inherit;border-radius:var(--r-tiny,4px)}
@media (hover:hover) and (pointer:fine){.v2 .sgx-re:hover{text-decoration:underline;text-underline-offset:2px}}
.v2 .sgx-ck{width:52px;height:52px;fill:none;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}
.v2 .sgx-ck circle{stroke:var(--ok-mark);stroke-dasharray:151;stroke-dashoffset:151;animation:v2-sgdraw .7s var(--ease) forwards}
.v2 .sgx-ck path{stroke:var(--ok-mark);stroke-dasharray:30;stroke-dashoffset:30;animation:v2-sgdraw .4s var(--ease) .55s forwards}
@keyframes v2-sgdraw{to{stroke-dashoffset:0}}
.v2 .sgx-bar{width:120px;height:3px;border-radius:var(--r-tiny,2px);background:var(--line);overflow:hidden;margin-top:var(--s-1)}
.v2 .sgx-bar i{display:block;height:100%;width:0;background:var(--accent-mark,var(--accent));animation:v2-sgbar 1.8s var(--ease) .6s forwards}
@keyframes v2-sgbar{to{width:100%}}
.v2 .sgx-rs{display:block;min-height:20px;font-size:12px;line-height:20px}
.v2 .sgx-ft :is(.sgx-go,.sgx-rs)[hidden]{display:none}
/* done: the green check and the welcome, and in the foot the workspace opening */
.v2 .sgx-done{display:flex;flex-direction:column;align-items:center;gap:var(--s-2);padding:var(--s-4) 0 0;font-size:13px;text-align:center}
.v2 .sgx-done>b{font-weight:500;font-size:14px}
.v2 .sgx-open{display:flex;flex-direction:column;align-items:center;gap:var(--s-2);padding-bottom:var(--s-4);font-size:13px}
.v2 .sgx-open .shim{font-size:inherit}
