:root[data-style="clean"] .v2 .fmx-go .shim{background-image:linear-gradient(90deg,var(--on-btn) 0%,var(--on-btn) 38%,color-mix(in srgb,var(--on-btn) 45%,transparent) 50%,var(--on-btn) 62%,var(--on-btn) 100%)}
