.v2 .pyx-sum{display:flex;flex-direction:column;margin-top:var(--s-1);padding-top:var(--s-4);border-top:1px solid color-mix(in srgb,var(--line) 50%,transparent);font-size:12.5px;line-height:18px;color:var(--fg2)}
