.v2 .pyx-go.ok .i{color:var(--ok-mark)}
:root[data-style="clean"] .v2 .pill.accent.pyx-go.ok:not([disabled]){background:linear-gradient(180deg,var(--btn2-1),var(--btn2-2));color:var(--fg);box-shadow:var(--btn2-depth);transform:none}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .pill.accent.pyx-go.ok:not([disabled]):is(:hover,:active){background:linear-gradient(180deg,var(--btn2-1),var(--btn2-2));color:var(--fg);box-shadow:var(--btn2-depth);transform:none}}
