.v2 .cmx-h{display:flex;align-items:center;gap:var(--s-3);min-height:20px;padding-bottom:var(--s-4);border-bottom:1px solid color-mix(in srgb,var(--line) 50%,transparent);font-size:13.5px;line-height:20px}
