.v2 .tkx-em-art::before{content:"";position:absolute;left:14px;top:16px;width:8px;height:8px;border-radius:50%;background:var(--ghost,var(--chip));box-shadow:0 16px 0 var(--ghost,var(--chip)),0 32px 0 var(--ghost-2,color-mix(in srgb,var(--chip) 55%,var(--surface)))}
