  .v2 .kbx.list .kbx-id,.v2 .kbx.list .kbx-m,.v2 .kbx.list .kbx-pr,.v2 .kbx.list .kbx-cr>:not(.kbx-pri){display:none}
  .v2 .kbx-pk{width:100%}
  .v2 .kbx-bk{left:var(--s-2);right:var(--s-2);max-width:none;transform:translateY(8px)}
  .v2 .kbx-bk.on{transform:none}
  .v2 .kbx-bk .lg{display:none}
  .v2 .kbx-bk .sh{display:inline}
  .v2 .kbx-bk .l{display:none}
  .v2 .kbx-bk .n{margin-right:auto}
}

/* ---------- Context menu ---------- */
/* an agent reply with a menu of its own: right-click, long-press, Shift+F10 or the Menu key opens it where you are, over the
   reply, and the reply never moves. The reply's content sits 16px in from every edge in every style. While its menu is open
   the reply takes a quiet, deeper fill (no ring or shadow round it). What the agent writes when asked (a summary, an
   explanation) appears under the reply as plain text with its label, once it is written; the reply grows to hold it, and
   shrinks to the Undo row when it is deleted (grow()). A short confirmation (Copied, Quoted) shows for a moment on the
   reply's head line, never as a line under the card */
.v2 .cxm{position:relative;width:100%;display:flex;flex-direction:column;gap:var(--s-2)}
.v2 .cxm.growing{overflow:visible}
.v2 .cxm-msg{padding:var(--s-4);display:flex;flex-direction:column;gap:var(--s-2);font-size:13.5px;line-height:1.55;-webkit-touch-callout:none;transition:background-color var(--t-fast) var(--ease)}
.v2 .cxm-msg:focus-visible{outline-offset:3px;border-radius:var(--r-card)}
.v2 .cxm-msg.on{background:color-mix(in srgb,var(--fg) 3%,var(--surface))}
.v2 .cxm-hd{display:flex;align-items:center;gap:var(--s-2);min-height:22px;font-size:13px}
.v2 .cxm-hd b{font-weight:500}
.v2 .cxm-hd .muted{font-size:12px}
.v2 .cxm-av{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;background:var(--accent-bg);color:var(--accent-fg,var(--accent))}
.v2 .cxm-pin,.v2 .cxm-ok{display:inline-flex;align-items:center;gap:4px;margin-left:auto;font-size:12px;color:var(--muted);white-space:nowrap}
.v2 .cxm-ok+.cxm-pin{margin-left:var(--s-2)}
.v2 .cxm-ok .i{color:var(--ok-mark)}
.v2 .cxm-ok{transition:opacity var(--t-fast) var(--ease)}
.v2 .cxm-ok.out{opacity:0}
.v2 .cxm-tx{margin:0;color:var(--fg)}
.v2 .cxm-out:empty{display:none}
.v2 .cxm-res{display:flex;flex-direction:column;gap:var(--s-1);margin-top:var(--s-1);font-size:13px;color:var(--fg2)}
.v2 .cxm-res .k{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)}
.v2 .cxm-res .k .i{color:var(--accent-fg,var(--accent))}
.v2 .cxm-res .w{animation:v2-tkword .42s var(--ease) backwards}
/* what an action did is said to screen readers here; on screen it shows on the reply's head line */
.v2 .cxm-note{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.v2 .cxm-gone{display:flex;align-items:center;justify-content:center;gap:var(--s-2);padding:var(--s-3);font-size:13px;color:var(--muted)}
.v2 .cxm :is(.pill,.ib):active{transform:none}
.v2 .cxm-pop,.v2 .cxm-pop2{top:0;left:0;min-width:220px}
.v2 .cxm-pop2{min-width:180px}
.v2 .cxm-pop .mi .r .i{color:var(--muted)}
.v2 .cxm-sub[aria-expanded="true"]{background:color-mix(in srgb,var(--fg) 5%,transparent)}
.v2 .cxm-del,.v2 .cxm-del .i{color:var(--bad)}
/* asking, its words lean a little toward the text colour so they keep APCA Lc 60 on the red tint in dark mode too */
.v2 .cxm-del.ask{background:var(--bad-bg)}
.v2 .cxm-del.ask,.v2 .cxm-del.ask .i{color:color-mix(in srgb,var(--bad) 85%,var(--fg))}
/* Clean: 22px corners and 16px in; the label of what the agent wrote is grey like the chrome; no red fill behind the delete
   that asks again, only its red words on the row's grey; the menus take the card's corners with their rows concentric */
:root[data-style="clean"] .v2 .cxm-res .k .i{color:var(--fg2)}
:root[data-style="clean"] .v2 .cxm-del.ask{background:var(--row)}
:root[data-style="clean"] .v2 :is(.cxm-pop,.cxm-pop2){padding:6px;border-radius:var(--r-card)}
:root[data-style="clean"] .v2 :is(.cxm-pop,.cxm-pop2) .mi{border-radius:calc(var(--r-card) - 6px)}
/* ---------- Progress and meter ---------- */
/* one run, three ways to read it: the ring is the whole run, the segments its steps (n of m), the bar the step in hand.
   Its colour says how it is going: the accent while it runs, grey while paused, red when a step fails, green once done */
.v2 .prg{padding:var(--s-4);display:flex;flex-direction:column;gap:var(--s-3);--prg-c:var(--accent-mark,var(--accent))}
.v2 .prg[data-s="paused"]{--prg-c:var(--line-strong)}
.v2 .prg[data-s="err"]{--prg-c:var(--bad-mark)}
.v2 .prg[data-s="done"]{--prg-c:var(--ok-mark)}
.v2 .prg-h{display:flex;align-items:center;gap:var(--s-3)}
.v2 .prg-ring{position:relative;width:44px;height:44px;flex:none;display:grid;place-items:center;color:var(--ok-mark)}
.v2 .prg-ring>svg{position:absolute;inset:0;width:100%;height:100%;transform:rotate(-90deg)}
.v2 .prg-ring circle{fill:none;stroke-width:3}
.v2 .prg-ring .tr{stroke:var(--chip)}
.v2 .prg-ring .fl{stroke:var(--prg-c);stroke-dasharray:0 100;stroke-linecap:round;transition:stroke-dasharray .6s var(--ease),stroke .3s}
/* not knowing how long it will take, the ring turns a short arc and the bar sweeps */
.v2 .prg[data-s="ind"] .prg-ring>svg{animation:v2-rot 1.1s linear infinite}
.v2 .prg[data-s="ind"] .prg-ring .fl{stroke-dasharray:25 100;transition:none}
.v2 .prg-pc{font-size:13px;font-weight:500;color:var(--fg);line-height:1;letter-spacing:-.02em}
.v2 .prg-t{flex:1;min-width:0;display:flex;flex-direction:column;font-size:13.5px;line-height:1.4}
.v2 .prg-t b{font-weight:500}
.v2 .prg-vt{font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .prg-st{flex:none}
/* the bare pause button reaches out by its glyph's inset, so the glyph ends on the content's right edge with the bars below */
.v2 .prg-btn{margin-right:-7px}
.v2 .prg-st.run{background:var(--accent-bg);color:var(--accent-fg,var(--accent))}
.v2 .prg-seg{display:flex;gap:var(--s-1)}
.v2 .prg-seg i,.v2 .prg-lin{position:relative;flex:none;height:6px;border-radius:calc(3px * var(--rk-s,var(--rk)));background:var(--chip);overflow:hidden}
.v2 .prg-seg i{flex:1}
.v2 .prg-seg b{position:absolute;inset:0;border-radius:inherit;background:var(--prg-c);transform-origin:left;transform:scaleX(var(--f,0));transition:transform .45s var(--ease),background .3s}
.v2 .prg-ll{display:flex;align-items:center;justify-content:space-between;gap:var(--s-2);min-height:28px;margin-bottom:calc(var(--s-1) * -1);font-size:12.5px;color:var(--fg2)}
.v2 .prg-ll .n{color:var(--muted)}
.v2 .prg-ll .e{display:flex;align-items:center;gap:6px;min-width:0;color:var(--bad)}
.v2 .prg-ll .e span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .prg-lin i{position:absolute;left:0;top:0;bottom:0;width:0;border-radius:inherit;background:var(--prg-c);transition:width .45s var(--ease),background .3s}
.v2 .prg-lin.ind i{width:32%;animation:v2-prgsweep 1.3s var(--ease-io) infinite;transition:none}
@keyframes v2-prgsweep{from{transform:translateX(-100%)}to{transform:translateX(320%)}}
.v2 .prg-meter{display:flex;flex-direction:column;gap:var(--s-2);margin-top:var(--s-1);padding-top:var(--s-4);border-top:1px solid color-mix(in srgb,var(--line) 50%,transparent)}
.v2 .prg-mh{display:flex;align-items:baseline;justify-content:space-between;gap:var(--s-2);font-size:13px}
.v2 .prg-mh b{font-weight:500;color:var(--fg)}
.v2 .prg-mh .muted{font-size:12.5px}
.v2 .prg-mb{position:relative;height:8px;border-radius:calc(4px * var(--rk-s,var(--rk)));background:var(--chip)}
.v2 .prg-mb .fl{position:absolute;left:0;top:0;bottom:0;width:0;border-radius:inherit;background:var(--accent-mark,var(--accent));transition:width .6s var(--ease),background .3s}
.v2 .prg-mb.warn .fl{background:var(--warn-mark)}
.v2 .prg-mb.bad .fl{background:var(--bad-mark)}
/* where the meter starts to warn: a notch through the bar at 75% and 90% */
.v2 .prg-mb .th{position:absolute;top:-3px;bottom:-3px;width:2px;margin-left:-1px;border-radius:1px;background:color-mix(in srgb,var(--fg) 35%,transparent)}
/* where the meter stops (a hard limit, such as runs pausing at 90%): a dashed line through the bar instead of a notch (owner, 10 Nov) */
.v2 .prg-mb .th.stop{top:-4px;bottom:-4px;width:0;margin-left:0;border-radius:0;background:none;border-left:1.5px dashed color-mix(in srgb,var(--fg) 55%,transparent)}
.v2 .prg-ml{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:var(--s-1) var(--s-2);min-height:20px;font-size:12px}
.v2 .prg-ml .tag .i{margin-left:-1px}
.v2 .prg-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@media (prefers-reduced-motion:reduce){.v2 .prg[data-s="ind"] .prg-ring>svg{animation:none}.v2 .prg-lin.ind i{animation:none;width:100%;opacity:.35}}
/* Clean: its content 16px in from every edge, the panel's own padding (owner, 18 Nov) */
/* Clean (owner, 21 Nov: "no different than soft, need more segmentation and clean components"): three sections. The run is an
   off-white head strip (the ring, Indexing the docs, its status chip and Pause, a ghost icon button) under a hairline; the steps
   bar and the step's own bar (Pages) are one section under it; Credits is a section of its own under a hairline, with its
   status and Resets Dec 1 in an off-white foot strip. Every track, the ring's too, is sunk with Clean's inner shadow, which
   lies over its fill; the meter's thresholds are crisp 1px hairlines */
:root[data-style="clean"] .v2 .prg.panel{padding:0;gap:0}
:root[data-style="clean"] .v2 .prg-h{padding:12px 16px;background:var(--strip);border-bottom:1px solid var(--line);border-radius:var(--r-card) var(--r-card) 0 0}
:root[data-style="clean"] .v2 .prg-btn{margin-right:-8px;border-radius:50%}
:root[data-style="clean"] .v2 .prg-seg{margin:16px 16px 0}
:root[data-style="clean"] .v2 .prg-ll{margin:8px 16px -4px}
:root[data-style="clean"] .v2 .prg-lin{margin:8px 16px 0}
:root[data-style="clean"] .v2 .prg-meter{margin-top:16px;padding:16px 16px 0;border-top:1px solid var(--line)}
:root[data-style="clean"] .v2 .prg-ml{margin:8px -16px 0;padding:12px 16px;min-height:44px;line-height:20px;background:var(--strip);border-top:1px solid var(--line);border-radius:0 0 var(--r-card) var(--r-card)}
:root[data-style="clean"] .v2 .prg :is(.prg-seg i,.prg-lin,.prg-mb){background:var(--soft);border-radius:var(--r-pill)}
:root[data-style="clean"] .v2 .prg :is(.prg-seg i,.prg-lin,.prg-mb)::after{content:"";position:absolute;inset:0;z-index:1;border-radius:inherit;box-shadow:var(--track-ring);pointer-events:none}
:root[data-style="clean"] .v2 .prg .prg-mb .th{z-index:2;width:1px;margin-left:-.5px;border-radius:0;background:color-mix(in srgb,var(--fg) 45%,transparent)}
:root[data-style="clean"] .v2 .prg .prg-mb .th.stop{width:0;border-left-width:1px;background:none}
:root[data-style="clean"] .v2 .prg-ring .tr{stroke:transparent}
:root[data-style="clean"] .v2 .prg-ring::before{content:"";position:absolute;inset:calc(100% * 3 / 72);border-radius:50%;background:var(--soft);box-shadow:var(--track-ring);-webkit-mask:radial-gradient(circle closest-side,transparent calc(100% * 27 / 33 - .5px),#000 calc(100% * 27 / 33));mask:radial-gradient(circle closest-side,transparent calc(100% * 27 / 33 - .5px),#000 calc(100% * 27 / 33))}
/* the words that say what the run is doing shimmer while it works (.shim, owner, 19 Nov): the sweep's colours, not the line's own */
.v2 :is(.prg-vt,.pva-st .w,.pvb-sum,.pvc-vt).shim{color:transparent}
/* ---------- Progress designs ---------- */
/* the homepage card's design switch (its footer tabs on designme.dev): Compact, Steps and Budget, three ways to show one agent
   run and what it costs, in the place of the ring and three bars (owner, 8 Nov). The registry, the code view and the
   component page install the classic component above (build.js leaves a data-designs="card" switch out of them) */
.v2 .dm.prg-dm>.dm-main{align-items:center}
/* words for screen readers only */
.v2 .prg-dm .sr{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
/* ---------- A · progressive disclosure ----------
   At rest: the run's name, its state in words, one bar for the whole run and the time left. Steps and Credits open
   layers with the detail: each step's count, timing and what it is on now; the run's spend and its share of the month */
.v2 .pva{width:100%;display:flex;flex-direction:column;padding:var(--s-4) var(--s-4) var(--s-2);font-size:13px;line-height:1.45;color:var(--fg);--pva-c:var(--accent-mark)}
.v2 .pva[data-s="paused"]{--pva-c:var(--line-strong)}
.v2 .pva[data-s="err"]{--pva-c:var(--bad)}
.v2 .pva[data-s="done"]{--pva-c:var(--ok-mark)}
.v2 .pva-top{display:flex;align-items:flex-start;gap:var(--s-3)}
.v2 .pva-id{flex:1;min-width:0}
.v2 .pva-name{font-size:14px;font-weight:500;line-height:20px}
.v2 .pva-st{display:flex;align-items:center;gap:var(--s-2);min-width:0;min-height:20px;margin-top:2px;color:var(--fg2)}
.v2 .pva-st .w{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .pva[data-s="err"] .pva-st{color:var(--bad)}
/* the state's mark: a dot that breathes while the run works, a still grey one while paused, an icon when it stops */
.v2 .pva-mk{position:relative;flex:none;display:grid;place-items:center;width:12px;height:12px}
.v2 .pva-mk>i{width:6px;height:6px;border-radius:50%;corner-shape:round;background:var(--pva-c)}
.v2 .pva-mk>i::after{content:"";position:absolute;inset:3px;border-radius:50%;corner-shape:round;background:var(--pva-c);opacity:0}
.v2 .pva:is([data-s="run"],[data-s="ind"]) .pva-mk>i::after{animation:v2-pvaping 1.8s var(--ease) infinite}
@keyframes v2-pvaping{0%{transform:scale(1);opacity:.45}80%,100%{transform:scale(2.6);opacity:0}}
.v2 .pva-mk .i{display:none}
.v2 .pva:is([data-s="err"],[data-s="done"]) .pva-mk>i{display:none}
.v2 .pva[data-s="err"] .pva-mk .e,.v2 .pva[data-s="done"] .pva-mk .d{display:block}
.v2 .pva[data-s="done"] .pva-mk{color:var(--ok)}
.v2 .pva-act{flex:none;display:flex;align-items:center;gap:var(--s-1);margin:-3px -6px 0 0}
.v2 .pva-act .pill{gap:6px}
.v2 .pva-act .ib[disabled]{color:var(--dm-dis);cursor:default}
/* the failure, in a sentence, under the state while the run is stopped */
.v2 .pva-err p{margin:0;padding-top:var(--s-1);font-size:12.5px;line-height:1.5;color:var(--fg2);text-wrap:pretty}
/* the one bar: the whole run, in proportion to how long each step takes; hairline gaps mark where steps meet */
.v2 .pva-bar{position:relative;height:6px;margin-top:var(--s-3);border-radius:calc(3px * var(--rk-s,var(--rk)));background:var(--chip);overflow:hidden}
.v2 .pva-fill{position:absolute;left:0;top:0;bottom:0;width:0;border-radius:inherit;background:var(--pva-c);transition:width .2s linear,background var(--t-fast)}
.v2 .pva[data-s="ind"] .pva-fill{width:30%;animation:v2-pvasweep 1.3s var(--ease-io) infinite;transition:none}
@keyframes v2-pvasweep{from{transform:translateX(-100%)}to{transform:translateX(340%)}}
.v2 .pva-tk{position:absolute;top:0;bottom:0;width:2px;margin-left:-1px;background:var(--surface)}
.v2 .pva[data-s="ind"] .pva-tk{opacity:0}
.v2 .pva-meta{display:flex;align-items:center;justify-content:space-between;gap:var(--s-2);min-height:28px;margin-top:var(--s-2);font-size:12.5px;color:var(--fg2)}
.v2 .pva-eta{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .pva-eta b{font-weight:500;color:var(--fg)}
/* the credits control: this run's spend, opening a layer with its projection and the month */
.v2 .pva-cr{position:relative;flex:none;display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 8px;margin-right:-8px;border-radius:var(--r-sm);color:var(--fg2);font-size:12.5px;transition:background var(--t-fast),color var(--t-fast)}
@media (hover:hover) and (pointer:fine){.v2 .pva-cr:hover{background:var(--row);color:var(--fg)}}
.v2 .pva-cr[aria-expanded="true"]{background:var(--chip);color:var(--fg)}
.v2 .pva-cr .v{font-weight:500;color:var(--fg)}
.v2 .pva-cr .cv{transition:transform var(--t) var(--ease)}
.v2 .pva-cr[aria-expanded="true"] .cv{transform:rotate(180deg)}
.v2 .pva-cr .wd{position:absolute;top:4px;left:19px;width:6px;height:6px;border-radius:50%;corner-shape:round;background:var(--warn-mark);box-shadow:0 0 0 1.5px var(--surface)}
.v2 .pva-sep{height:1px;margin-top:var(--s-3);background:color-mix(in srgb,var(--line) 50%,transparent)}
/* Steps: the toggle that opens the step list */
.v2 .pva-tog{display:flex;align-items:center;gap:var(--s-2);width:calc(100% + var(--s-4));height:36px;margin:var(--s-1) calc(var(--s-2) * -1) 0;padding:0 var(--s-2);border-radius:var(--r-sm);font-size:13px;text-align:left;transition:background var(--t-fast)}
@media (hover:hover) and (pointer:fine){.v2 .pva-tog:hover{background:var(--row)}}
.v2 .pva-tog .cv{color:var(--fg2);transition:transform var(--t) var(--ease)}
.v2 .pva-tog[aria-expanded="true"] .cv{transform:rotate(180deg)}
.v2 .pva-tog .l{font-weight:500}
.v2 .pva-tog .n{min-width:0;flex:1;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .pva-tog .el{flex:none;color:var(--muted);font-size:12.5px}
/* the step list */
.v2 .pva-list{list-style:none;margin:0;padding:0 0 var(--s-2);display:flex;flex-direction:column;gap:2px}
.v2 .pva-sh{display:grid;grid-template-columns:16px minmax(0,1fr) auto 40px 12px;align-items:center;column-gap:var(--s-2);width:100%;min-height:32px;padding:0 var(--s-2);border-radius:var(--r-sm);font-size:13px;text-align:left}
.v2 button.pva-sh{transition:background var(--t-fast)}
@media (hover:hover) and (pointer:fine){.v2 button.pva-sh:hover{background:var(--row)}}
.v2 .pva-si{display:grid;place-items:center;width:16px;height:16px;color:var(--fg2)}
.v2 .pva-si .spin{width:11px;height:11px;color:var(--accent-mark)}
.v2 .pva-o{width:9px;height:9px;border-radius:50%;corner-shape:round;box-shadow:inset 0 0 0 1.5px var(--line-strong)}
.v2 .pva-sn{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .pva-sc,.v2 .pva-sd{font-size:12.5px;color:var(--muted);white-space:nowrap}
.v2 .pva-sd{text-align:right}
.v2 .pva-sv{display:grid;place-items:center;color:var(--fg2)}
.v2 .pva-sv .i{transition:transform var(--t) var(--ease)}
.v2 button.pva-sh[aria-expanded="true"] .pva-sv .i{transform:rotate(180deg)}
.v2 .pva-s[data-st="up"] .pva-sn{color:var(--muted)}
.v2 .pva-s:is([data-st="live"],[data-st="err"]) .pva-sn{font-weight:500}
.v2 .pva-s[data-st="live"] .pva-sc{color:var(--fg)}
.v2 .pva-s[data-st="err"] .pva-si{color:var(--bad)}
.v2 .pva-s[data-st="err"] .pva-sc{color:var(--fg)}
/* a step's detail sits under its name: what it is on now, or its log once it is done */
.v2 .pva-sxi{display:flex;flex-direction:column;gap:2px;padding:0 var(--s-2) var(--s-2) calc(var(--s-2) * 2 + 16px);font-size:12.5px;line-height:1.5;color:var(--fg2)}
.v2 .pva-sxi p{margin:0;text-wrap:pretty}
.v2 .pva-now{display:flex;align-items:baseline;gap:6px;min-width:0}
.v2 .pva-now .p{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--fg)}
.v2 .pva-s[data-st="err"] .pva-e{color:var(--bad)}
.v2 .pva-k{flex:none;color:var(--muted)}
