/* text buttons: no fill until hovered, then the faintest grey */
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 .pill.ghost:hover{background:var(--row)}}
/* the controls in a head or foot strip sit on the content's 16px column at the sides, as the rows do, and 8px from the
   strip's own top and bottom (owner, 21 Nov: "ok do it, apply everywhere", replacing 8px from the card's edges) */
:root[data-style="clean"] .v2 :is(.atx-ft,.atx-ctx-ft){padding-right:16px}
/* one hover for every ghost and icon button (owner, 21 Nov: "you use like 10 different hover styles"): the quiet grey of what
   it sits on (--row) in the button's own shape, with no edge, shadow or change of size, in every style. On an off-white strip
   the grey is a step under the strip, so it shows as it does on the card. (A remove × inside a filled chip, a tinted banner
   or the ink save bar takes a little of its own colour instead, color-mix(currentColor 12%), as no grey shows on a fill) */
/* the cards that set a stronger grey of their own for the stage take Clean's, so every hover in Clean is the same fill */
:root[data-style="clean"] .v2 :is(.tst-t,.tsk-c,.lva,.plx,.ssx,.ahx,.lnx,.dnx,.cmx,.ntx.panel,.ivx,.rxx,.rgx,.wsx){--row:inherit}
/* menus: rows with 10px corners, the hover and the picked row's fill easing in and out over 220ms */
:root[data-style="clean"] .v2 .mi{border-radius:10px;transition:background-color var(--t-fast) var(--ease),color var(--t-fast) var(--ease)}
:root[data-style="clean"] .v2 .pop :is(.mi[aria-checked="true"],.mi[aria-selected="true"],[role="option"][aria-selected="true"]){background:var(--row-on)}
:root[data-style="clean"] .v2 .ib{transition:background-color var(--t-fast) var(--ease),color var(--t-fast) var(--ease),transform var(--t-fast) var(--ease)}
/* a field's own Send (Comments, Composer, Attachment tray's composer, Agent lanes' note; owner, 21 Nov): it sits in the field's
   corner with the same room above, below and beside it, and its corners are the field's less that room (each component sets
   the radius). Empty, it is a quiet glyph with no fill; once there is something to send, the ink button fades in under it.
   Only the ink presses */
:root[data-style="clean"] .v2 :is(.cmx-go,.cpx-send,.atx-cmp-send,.aln-cw-go){position:relative;isolation:isolate;background:none;box-shadow:none;transition:transform var(--t-fast) var(--ease),color var(--t-fast) var(--ease)}
:root[data-style="clean"] .v2 :is(.cmx-go,.cpx-send,.atx-cmp-send,.aln-cw-go)::before{content:'';position:absolute;inset:0;z-index:-1;border-radius:inherit;background:linear-gradient(180deg,var(--btn-1),var(--btn-2));box-shadow:var(--btn-depth);opacity:0;pointer-events:none;transition:opacity var(--t-fast) var(--ease),box-shadow var(--t-fast) var(--ease)}
:root[data-style="clean"] .v2 :is(.cmx-go,.cpx-send,.atx-cmp-send,.aln-cw-go):not([disabled]){color:var(--on-btn)}
:root[data-style="clean"] .v2 :is(.cmx-go,.cpx-send,.atx-cmp-send,.aln-cw-go):not([disabled])::before{opacity:1}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 :is(.cmx-go,.cpx-send,.atx-cmp-send,.aln-cw-go):not([disabled]):hover::before{background:linear-gradient(180deg,color-mix(in srgb,var(--btn-1) 88%,#808080),var(--btn-2))}}
:root[data-style="clean"] .v2 :is(.cmx-go,.cpx-send,.atx-cmp-send,.aln-cw-go):not([disabled]):active{transform:scale(.97)}
:root[data-style="clean"] .v2 :is(.cmx-go,.cpx-send,.atx-cmp-send,.aln-cw-go):not([disabled]):active::before{box-shadow:var(--btn-press)}
:root[data-style="clean"] .v2 :is(.cmx-go,.cpx-send,.atx-cmp-send,.aln-cw-go)[disabled]{color:var(--dis);transform:none}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] .v2 :is(.cmx-go,.cpx-send,.atx-cmp-send,.aln-cw-go)::before{transition:none}}
/* the gliding highlight in a menu or a list (hoverGlide() in the core script; owner, 21 Nov): one fill, the list's own ::before
   or ::after, drawn under its rows. It moves and resizes to the row under the pointer, the keyboard's row or the arrows' row over
   220ms with Clean's ease, and fades in and out as the pointer enters and leaves the list; with reduced motion it only fades.
   The rows' own hover fills give way to it; a picked row (data-hgr="k") keeps its stronger fill, which shows over it */
:root[data-style="clean"] .v2 .hg{isolation:isolate}
:root[data-style="clean"] .v2 .hg.hg-pos{position:relative}
:root[data-style="clean"] .v2 .hg[data-hg="b"]::before,:root[data-style="clean"] .v2 .hg[data-hg="a"]::after{content:"";position:absolute;left:0;top:0;z-index:-1;pointer-events:none;width:var(--hg-w,0px);height:var(--hg-h,0px);transform:translate(var(--hg-x,0px),var(--hg-y,0px));border-radius:var(--hg-r,10px);background:var(--hg-bg,var(--row));opacity:var(--hg-o,0);transition:opacity var(--t-fast) var(--ease),transform var(--t-fast) var(--ease),width var(--t-fast) var(--ease),height var(--t-fast) var(--ease),border-radius var(--t-fast) var(--ease)}
:root[data-style="clean"] .v2 .hg.hg-jump[data-hg="b"]::before,:root[data-style="clean"] .v2 .hg.hg-jump[data-hg="a"]::after{transition:opacity var(--t-fast) var(--ease)}
:root[data-style="clean"] .v2 .hg [data-hgr=""]{background-color:transparent!important}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] .v2 .hg[data-hg="b"]::before,:root[data-style="clean"] .v2 .hg[data-hg="a"]::after{transition-property:opacity!important;transition-duration:var(--t-fast)!important}}
/* switchers: a white knob with a hairline and a 1px shadow, gliding on a grey track with a soft inner shadow (the site's own
   switches and Segmented control's alike) */
:root[data-style="clean"] .v2 :is(.seg2,.sgc-seg){box-shadow:var(--track-ring)}
:root[data-style="clean"] .v2 :is(.seg2 .knob,.sgc-seg .sgc-k){background:var(--knob);box-shadow:var(--knob-shadow);transition:left var(--t) var(--ease),width var(--t) var(--ease)}
:root[data-style="clean"] .v2 :is(.seg2,.sgc-seg) button{color:var(--muted);font-weight:500;transition:color var(--t-fast) var(--ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .v2 :is(.seg2 button[aria-pressed="true"],.sgc-seg button:is(:hover,[aria-selected="true"],[aria-checked="true"])){color:var(--fg)}}
/* toggles: ink when on (a switcher is chrome), a knob with a hairline, and a soft inner shadow in the track */
:root[data-style="clean"] .v2 .toggle[aria-checked="true"]{background:var(--btn-2);box-shadow:inset 0 0 0 1px var(--btn-2),inset 0 2px 4px -1px rgba(0,0,0,.3)}
:root[data-style="clean"] .v2 .toggle[aria-checked="true"]::after{background:var(--on-btn)}
:root[data-style="clean"] .v2 .toggle{box-shadow:inset 0 0 0 1px rgba(0,0,0,.05),inset 0 2px 4px -1px rgba(0,0,0,.18)}
:root[data-style="clean"] .v2 .toggle::after{box-shadow:0 0 0 .5px rgba(0,0,0,.1),0 1px 2px rgba(0,0,0,.2);transition:transform var(--t) var(--ease)}

/* a card far from the screen is hidden and its animations paused (see dm-idle in the mount script) */
/* its contents are skipped entirely (no layout, paint or layers) while the stage keeps its measured height */
.comp.dm-idle .stage-in{content-visibility:hidden}
.comp.dm-idle .stage-in *,.comp.dm-idle .stage-in *::before,.comp.dm-idle .stage-in *::after{animation-play-state:paused!important}
/* base for the mount root, which sits inside the site's stage */
.v2{font-family:var(--sans);font-size:14px;line-height:1.5;color:var(--fg);font-weight:400;letter-spacing:normal;text-align:left;-webkit-font-smoothing:antialiased}
.v2.stage-in{display:block}
.v2-layer{position:static}
/* the variant switch lives in the card footer on the site */
.v2 .dm>.demo{display:none}
.v2-host{overflow:visible}
